import type OpenFin from '@openfin/core';

import { Page } from '@common/api/pages/shapes';
import {
    getBrowserChannelClient,
    getWorkspacePlatformChannelClient,
    WorkspacePlatformChannelAction
} from '@common/api/protocol/workspace-platform';

import { DockProviderConfig } from '@client/index';

import type {
    CreateSavedPageRequest,
    CreateSavedWorkspaceRequest,
    UpdateSavedPageRequest,
    UpdateSavedWorkspaceRequest,
    Workspace,
    WorkspacePlatformStorage
} from '../shapes';

import { getCurrentSync } from '.';

export const getStorageApi = (identity: OpenFin.ApplicationIdentity): WorkspacePlatformStorage => ({
    createPage: async (req: CreateSavedPageRequest) => {
        const client = await getBrowserChannelClient(identity);
        return client.dispatch(WorkspacePlatformChannelAction.CreateSavedPageInternal, req);
    },
    deletePage: async (id: string) => {
        const client = await getBrowserChannelClient(identity);
        return client.dispatch(WorkspacePlatformChannelAction.DeleteSavedPageInternal, id);
    },
    updatePage: async (req: UpdateSavedPageRequest) => {
        const client = await getBrowserChannelClient(identity);
        return client.dispatch(WorkspacePlatformChannelAction.UpdateSavedPageInternal, req);
    },
    getPage: async (id: string) => {
        const client = await getBrowserChannelClient(identity);
        return client.dispatch(WorkspacePlatformChannelAction.GetSavedPage, id);
    },
    getPages: async (query?: string): Promise<Page[]> => {
        const client = await getBrowserChannelClient(identity);
        return client.dispatch(WorkspacePlatformChannelAction.GetSavedPages, query);
    },
    savePage: async (page: Page) => {
        const client = await getBrowserChannelClient(identity);
        return client.dispatch(WorkspacePlatformChannelAction.SavePage, page);
    },
    createWorkspace: async (req: CreateSavedWorkspaceRequest) => {
        const client = await getWorkspacePlatformChannelClient(identity);
        return client.dispatch(WorkspacePlatformChannelAction.CreateSavedWorkspace, req);
    },
    deleteWorkspace: async (id: string) => {
        const platform = getCurrentSync();
        const workspace = await platform.getCurrentWorkspace();
        if (workspace.workspaceId === id) {
            throw new Error(`Cannot delete current active workspace ${workspace.title}`);
        }
        const client = await getWorkspacePlatformChannelClient(identity);
        return client.dispatch(WorkspacePlatformChannelAction.DeleteSavedWorkspace, id);
    },
    updateWorkspace: async (req: UpdateSavedWorkspaceRequest) => {
        const client = await getWorkspacePlatformChannelClient(identity);
        return client.dispatch(WorkspacePlatformChannelAction.UpdateSavedWorkspace, req);
    },
    getWorkspace: async (id: string) => {
        const client = await getWorkspacePlatformChannelClient(identity);
        return client.dispatch(WorkspacePlatformChannelAction.GetSavedWorkspace, id);
    },
    getWorkspaces: async (query?: string): Promise<Workspace[]> => {
        const client = await getWorkspacePlatformChannelClient(identity);
        return client.dispatch(WorkspacePlatformChannelAction.GetSavedWorkspaces, query);
    },
    getWorkspacesMetadata: async (query?: string): Promise<Pick<Workspace, 'workspaceId' | 'title'>[]> => {
        const client = await getWorkspacePlatformChannelClient(identity);
        return client.dispatch(WorkspacePlatformChannelAction.GetSavedWorkspacesMetadata, query);
    },
    saveWorkspace: async (workspace: Workspace) => {
        const client = await getWorkspacePlatformChannelClient(identity);
        return client.dispatch(WorkspacePlatformChannelAction.SaveWorkspace, workspace);
    },
    getDockProviderConfig: async (id: string) => {
        const client = await getWorkspacePlatformChannelClient(identity);
        return client.dispatch(WorkspacePlatformChannelAction.GetDockProviderConfig, id);
    },
    saveDockProviderConfig: async (config: DockProviderConfig) => {
        const client = await getWorkspacePlatformChannelClient(identity);
        return client.dispatch(WorkspacePlatformChannelAction.SaveDockProviderConfig, config);
    }
});
