import { createLogger } from '@common/utils/logger';

const logger = createLogger('common.debounce');

const makeDebouncedFunc = <T extends (...args: any[]) => Promise<any>>(func: T, debounceTimeout = 0): T => {
    let isDebounced = false;
    let debouncedArgs: any[];
    let funcPromise: Promise<void>;

    const runFunc = async (args: any[]): Promise<any> => {
        const v = await func(...args);
        if (isDebounced) {
            await new Promise((res) => setTimeout(res, debounceTimeout));
            const nextArgs = debouncedArgs;
            debouncedArgs = undefined;
            isDebounced = false;
            return runFunc(nextArgs);
        }
        return v;
    };

    const handleFunc: any = (...args: any[]) => {
        if (!funcPromise) {
            funcPromise = runFunc(args)
                .catch((err: Error) => {
                    logger.error('makeDebouncedFunc', 'Error in debounced function', {
                        error: err instanceof Error ? err.message : String(err)
                    });
                    throw err;
                })
                .finally(() => {
                    funcPromise = undefined;
                });
        } else {
            isDebounced = true;
            debouncedArgs = args;
        }
        return funcPromise;
    };

    return handleFunc;
};

/**
 * Debounce a specified function.
 *
 * When the debounced function is called, the underlying wrapped function
 * will be called.
 *
 * If the function is called again while the promise returned by the wrapped
 * function is still resolving, the call will be blocked until the promise has
 * resolved.
 *
 * Once the promise has been resolved, the wrapped function will be called again
 * after a specified debounce timeout.
 *
 */
export default makeDebouncedFunc;
