import { createSlice } from '@reduxjs/toolkit';

import { ColorSchemeOptionType } from '@client-platform/shapes';

import type { ComputedTheme } from '../api/theming';

export interface TargetThemingRootState {
    targetTheming: {
        isFetchingTheme: boolean;
        currentTheme: ComputedTheme | undefined;
        hasTriedFetch: boolean;
        currentScheme: ColorSchemeOptionType | undefined;
    };
}

export const targetThemingSlice = createSlice({
    name: 'targetTheming',
    initialState: {
        currentTheme: undefined,
        isFetchingTheme: true,
        hasTriedFetch: false,
        currentScheme: undefined
    } as TargetThemingRootState['targetTheming'],
    reducers: {
        setTheme: (state, action) => {
            state.currentTheme = action.payload;
        },
        setIsFetchingTheme: (state, action) => {
            state.isFetchingTheme = action.payload;
            state.hasTriedFetch = true;
        },
        setCurrentScheme: (state, action) => {
            state.currentScheme = action.payload;
        }
    }
});

export const { setTheme, setIsFetchingTheme, setCurrentScheme } = targetThemingSlice.actions;

export const selectTargetTheming = (state: TargetThemingRootState) => state.targetTheming?.currentTheme;

export const selectCurrentScheme = (state: TargetThemingRootState) => state.targetTheming?.currentScheme;

export const selectHasTriedFetch = (state: TargetThemingRootState) => state.targetTheming?.hasTriedFetch;

export const selectIsFetchingTheme = (state: TargetThemingRootState) => state.targetTheming?.isFetchingTheme;

export default targetThemingSlice.reducer;
