import type OpenFin from '@openfin/core';

import { getCachedManifest } from '@common/utils/application';
import makeGetChannelClient from '@common/utils/channels';
import { createLogger } from '@common/utils/logger';
import { notificationCenterOFIdentity } from '@common/utils/window';

const logger = createLogger('common.protocol.notifications');

import { ColorSchemeOptionType } from '@client-platform/shapes';

import { NotificationsCustomManifestOptions } from '../shapes/notifications';

export const NOTIFICATIONS_SYNC_CHANNEL = 'of-workspace-notifications-sync';

export enum NotificationsChannelAction {
    UpdatePlatformThemeScheme = 'update-platform-theme-scheme'
}

export interface UpdatePlatformSchemePayload {
    scheme: ColorSchemeOptionType;
}

interface NotificationsSyncChannelClient extends OpenFin.ChannelClient {
    dispatch(
        action: NotificationsChannelAction.UpdatePlatformThemeScheme,
        payload: UpdatePlatformSchemePayload
    ): Promise<void>;
}

export type ManifestNotificationsConfig = {
    notifications?: {
        customManifest?: NotificationsCustomManifestOptions;
    };
};

export async function getNotificationCenterUuid(): Promise<string> {
    try {
        const manifest = (await getCachedManifest()) as ManifestNotificationsConfig;
        const customManifestUuid = manifest?.notifications?.customManifest?.manifestUuid;
        if (customManifestUuid) {
            return customManifestUuid;
        }
        return notificationCenterOFIdentity.uuid;
    } catch (error) {
        logger.warn('getNotificationCenterUuid', 'Could not get manifest options for notifications, using default', {
            error: error instanceof Error ? error.message : String(error)
        });
        return notificationCenterOFIdentity.uuid;
    }
}

export async function getSyncChannelName(): Promise<string> {
    const uuid = await getNotificationCenterUuid();
    if (uuid !== notificationCenterOFIdentity.uuid) {
        return `${uuid}-${NOTIFICATIONS_SYNC_CHANNEL}`;
    }
    return NOTIFICATIONS_SYNC_CHANNEL;
}

let syncChannelClientPromise: Promise<NotificationsSyncChannelClient>;

export const getNotificationsSyncChannelClient = async (): Promise<NotificationsSyncChannelClient> => {
    if (!syncChannelClientPromise) {
        const channelName = await getSyncChannelName();
        const makeChannelClient = makeGetChannelClient(channelName);
        syncChannelClientPromise = makeChannelClient();
    }
    return syncChannelClientPromise;
};
