import React, { createContext, useContext } from 'react';

import { getEnterpriseBaseUrlFromHref } from '@enterprise/utils/base-url';

interface BaseUrlContextType {
    browserBaseUrl: string;
}

const BaseUrlContext = createContext<BaseUrlContextType | undefined>(undefined);

export const BrowserBaseUrlProvider = ({ children }: { children: React.ReactNode }) => {
    const browserBaseUrl = typeof window !== 'undefined' ? getEnterpriseBaseUrlFromHref(window.location.href) : '';

    return <BaseUrlContext.Provider value={{ browserBaseUrl }}>{children}</BaseUrlContext.Provider>;
};

export const useBaseUrl = (): BaseUrlContextType => {
    const context = useContext(BaseUrlContext);
    if (!context) {
        throw new Error('useBaseUrl must be used within a BrowserBaseUrlContextProvider');
    }
    return context;
};
