import { useEffect } from 'react';

import type OpenFin from '@openfin/core';

import { Flag, flag, flags } from '@common/api/flags';

import { usePlatformProviders } from '@common/hooks/context';
import { getCachedAppInfo } from '@common/utils/application';
import { setTags } from '@sentry/react';

declare const SENTRY_DSN: string;
const sentryDSN = SENTRY_DSN;

declare const COMMIT_SHA: string;
const commitSha = COMMIT_SHA;

/**
 * Intialize sentry error reporting.
 * Sentry is disabled by default and must be explicitly enabled via the SentryEnabled flag
 * in manifest overrides or Desktop Owner Settings.
 */
export function initSentry() {
    flag(Flag.SentryEnabled, async () => {
        if (!sentryDSN || typeof window === 'undefined') return;
        const sentry = await import('@sentry/react');
        sentry.init({
            enabled: true,
            dsn: sentryDSN,
            release: commitSha,
            environment: ENV,
            maxBreadcrumbs: 30
        });

        // Tell Sentry which Flags are enabled
        sentry.setContext('flags', flags);
    });
}

type WorkspaceSentryTags = {
    manifestUrl: string;
    licenseKey: string;
    runttime: string;
    rvmVersion: string;
};

export const useSentryTags = () => {
    const { activeProvider } = usePlatformProviders<'dock' | 'storefront'>();

    const getRvmVersion = async () => {
        let rvmVersion = 'unknown';

        try {
            rvmVersion = (await fin.System.getRvmInfo()).version;
        } catch (e) {
            // rvm probably doesn't exist
            // (likley we are on a mac)
        }
        return rvmVersion;
    };

    const updateApplicationTags = async () => {
        if (!activeProvider?.platformIdentity) return;
        const { setTags } = await import('@sentry/react');
        const appInfo = await fin.Application.wrapSync(activeProvider.platformIdentity).getInfo();
        setTags({
            manifestUrl: appInfo.manifestUrl,
            licenseKey: appInfo.manifest.licenseKey
        } as Partial<WorkspaceSentryTags>);
    };

    const updateSystemTags = async () => {
        const { setTags } = await import('@sentry/react');
        const runtime = await fin.System.getVersion();
        const rvmVersion = await getRvmVersion();
        setTags({
            runtime,
            rvmVersion
        } as Partial<WorkspaceSentryTags>);
    };

    useEffect(() => {
        updateSystemTags();
    }, []);

    useEffect(() => {
        updateApplicationTags();
    }, [activeProvider]);
};

export const useSentryTagsBrowser = () => {
    const setSentryTags = async () => {
        const applicationInfo = await getCachedAppInfo();
        let rvmInfo: OpenFin.RVMInfo | undefined;
        try {
            rvmInfo = await fin.System.getRvmInfo();
        } catch (e) {}

        setTags({
            manifestUrl: applicationInfo.manifestUrl,
            licenseKey: applicationInfo.manifest.licenseKey,
            runttime: applicationInfo.runtime.version,
            rvmVersion: rvmInfo?.version ?? 'unknown'
        } as Partial<WorkspaceSentryTags>);
    };

    useEffect(() => {
        setSentryTags();
    }, []);
};
