import { isFin } from './env';

type ListenerMap<
    EventMap extends {
        [key: string | number]: any[];
    }
> = Map<keyof EventMap, Set<(...payload: EventMap[keyof EventMap]) => void>>;

/**
 * Make a function for emitting an event across all windows in same domain.
 * @param listeners the registered set of listeners for each event type.
 * @param channel the broadcast channel for emitting events between windows in the same domain.
 */
function makeEmit<
    EventMap extends {
        [key: string | number]: any[];
    }
>(listeners: ListenerMap<EventMap>, postMessage?: (args: any) => any) {
    return async <EventKey extends keyof EventMap>(event: EventKey, ...payload: EventMap[EventKey]) => {
        if (listeners.has(event)) {
            listeners.get(event).forEach((listener) => listener(...payload));
        }
        if (postMessage) await postMessage({ event, payload });
    };
}

/**
 * Make a function for adding a listener for a particular event type.
 * @param listeners the set of listeners to add new listeners to for each event type.
 * @param channel the broadcast channel for listening for events between windows in the same domain.
 */
function makeAddListener<
    EventMap extends {
        [key: string | number]: any[];
    }
>(listeners: ListenerMap<EventMap>, addEventListener?: (listener: (args: any) => any) => any) {
    if (addEventListener) {
        addEventListener((msg) => {
            const { event, payload } = msg;
            if (listeners.has(event)) {
                listeners.get(event).forEach((listener) => listener(...payload));
            }
        });
    }
    return <EventKey extends keyof EventMap>(event: EventKey, listener: (...payload: EventMap[EventKey]) => void) => {
        if (!listeners.has(event)) {
            listeners.set(event, new Set());
        }
        listeners.get(event).add(listener);
    };
}

/**
 * Make a function for adding a listener for a particular event type.
 * @param listeners the set of listeners to add new listeners to for each event type.
 * @param channel the broadcast channel for listening for events between windows in the same domain.
 */
function makeOnce<
    EventMap extends {
        [key: string | number]: any[];
    }
>(listeners: ListenerMap<EventMap>) {
    return <EventKey extends keyof EventMap>(event: EventKey, listener: (...payload: EventMap[EventKey]) => void) => {
        if (!listeners.has(event)) {
            listeners.set(event, new Set());
        }
        const subListeners = listeners.get(event);
        const onceListener = (...args: EventMap[EventKey]) => {
            listener(...args);
            subListeners.delete(onceListener);
        };
        subListeners.add(onceListener);
    };
}

/**
 * Make a function for removing a listener for a particular event type.
 * @param listeners the registered set of listeners for each event type.
 */
function makeRemoveListener<
    EventMap extends {
        [key: string | number]: any[];
    }
>(listeners: ListenerMap<EventMap>) {
    return <EventKey extends keyof EventMap>(event: EventKey, listener: (...payload: EventMap[EventKey]) => void) => {
        if (listeners.has(event)) {
            listeners.get(event).delete(listener);
        }
    };
}

/**
 * Creates an event emitter that is shared between all windows within the same domain.
 */
export default function makeSharedEmitter<
    EventMap extends {
        [key: string | number]: any[];
    }
>(id: string) {
    const listeners: ListenerMap<EventMap> = new Map();
    return {
        emit: makeEmit<EventMap>(listeners, (msg) => isFin && fin.InterApplicationBus.publish(id, msg)),

        addListener: makeAddListener<EventMap>(
            listeners,
            (listener) => isFin && fin.InterApplicationBus.subscribe({ uuid: fin.me.uuid }, id, listener)
        ),
        /**
         * Creates a listener for a particular UUID instead of ApplicationUUID.Workspace.
         * @param uuid The UUID of the application to subscribe to.
         */
        addListenerWithUUID: (uuid: string) =>
            makeAddListener<EventMap>(
                listeners,
                (listener) => isFin && fin.InterApplicationBus.subscribe({ uuid }, id, listener)
            ),
        removeListener: makeRemoveListener<EventMap>(listeners),
        once: makeOnce<EventMap>(listeners)
    };
}
