import { isEnvProd, isWindowDefined } from '@common/utils/env';
import { pascalize } from '@common/utils/strings';

import { getOverrides } from '@common/api/overrides';

export enum Flag {
    WorkspaceStorefrontEnabled = 'WorkspaceStorefrontEnabled',
    SentryEnabled = 'SentryEnabled',
    WorkspaceDockEnabled = 'WorkspaceDockEnabled',
    WorkspaceHomeEnabled = 'WorkspaceHomeEnabled',
    DevDebug = 'DevDebug'
}

export type WorkspaceFlags = Record<Flag, boolean>;

/**
 * Consume flags from the environment.
 */
declare const WORKSPACE_FLAGS: Partial<WorkspaceFlags>;
export const flags: Partial<WorkspaceFlags> = typeof WORKSPACE_FLAGS !== 'undefined' ? WORKSPACE_FLAGS : {};

/**
 * Flags that are allowed to be overridden.
 */
const overridableFlags: Flag[] = [
    Flag.SentryEnabled,
    Flag.WorkspaceStorefrontEnabled,
    Flag.WorkspaceDockEnabled,
    Flag.WorkspaceHomeEnabled
];

let flagsInitialized = false;

/**
 * Initialize flags from overrides. This should be called early in the application lifecycle.
 * This is a no-op if flags have already been initialized.
 */
export const initializeFlags = async (): Promise<void> => {
    if (flagsInitialized) return;
    flagsInitialized = true;

    const overrides = await getOverrides();
    Object.entries(overrides.flags || {}).forEach(([k, v]) => {
        const key = pascalize(k);
        if (overridableFlags.some((f) => f === key)) {
            flags[key as Flag] = v;
        }
    });
};

// Initialize flags immediately when in a browser environment with fin API
if (isWindowDefined) {
    initializeFlags();
}

/**
 * Flag Interface --
 *
 * @example Enabled / Disabled Closures
 * flag(
 *     'feature',
 *     () => 'Enabled Feature',
 *     () => 'Disabled Feature'
 * );
 *
 * @example Enabled only
 * flag('feature', myFeatureFunc);
 *
 * @example Boolean
 * flag('feature');
 */
export function flag<EnabledReturn, DisabledReturn>(
    flagName: Flag,
    cbEnabled?: () => EnabledReturn,
    cbDisabled?: () => DisabledReturn
): EnabledReturn | DisabledReturn | boolean {
    if (flags) {
        // eslint-disable-next-line no-nested-ternary
        return flags[flagName] === true ? (cbEnabled ? cbEnabled() : true) : cbDisabled ? cbDisabled() : false;
    }
    throw new Error('Flags must be initialized.');
}

declare global {
    interface Window {
        __WORKSPACE_FLAGS__: typeof flags;
    }
}

if (!isEnvProd && isWindowDefined) {
    // eslint-disable-next-line no-underscore-dangle
    window.__WORKSPACE_FLAGS__ = flags;
}
