const logger = createLogger('common.layout');

export type LayoutDOMEventType =
    /**
     * Fired when a tab is created in a container. (Emmitted by ??)
     */
    | 'tabs-list-resized'
    /**
     * Fired when a tab is created in a container. (Emmitted by core)
     */
    | 'tab-created'
    /**
     * Fired when a new container/stack is created. (Emitted by Golden Layout)
     */
    | 'container-created'
    /**
     * Fired when the layout container is ready to be used. (Emitted by us)
     */
    | 'container-resized'
    /**
     * Fired when a view item container is resized (e.g., via separator drag). (Emitted by us)
     */
    | 'view-container-resized'
    | 'tab-closed';

export type LayoutDOMEvent =
    | {
          type: Extract<LayoutDOMEventType, 'container-resized'>;
      }
    | {
          type: Extract<LayoutDOMEventType, 'view-container-resized'>;
      }
    | {
          type: Extract<LayoutDOMEventType, 'tab-created' | 'tab-closed'>;
          detail: {
              containerSelector: string;
              tabSelector: string;
              name: string;
              topic: string;
              type: string;
              uuid: string;
              originalElement: HTMLElement;
          };
          isInitialized: boolean;
          target: HTMLElement;
      }
    | {
          type: Extract<LayoutDOMEventType, 'container-created'>;
          detail?: {
              containerSelector?: string;
              [key: string]: any;
          };
          target?: HTMLElement;
          originalElement?: HTMLElement;
      }
    | {
          type: Extract<LayoutDOMEventType, 'tabs-list-resized'>;
      };

export type LayoutDOMEventListener = (ev: LayoutDOMEvent) => void;

export const VIEW_NAME_PREFIX = 'internal-generated-view-' as const;

export const getViewNameFromTabId = (tabId: string) => {
    // strips 'tab-' prefix
    return tabId.substring(4);
};

export const getFirstActiveViewFromLayout = (identity: OpenFin.LayoutIdentity): OpenFin.Identity | undefined => {
    const layoutContainer = document.getElementById(identity.layoutName);
    if (!layoutContainer) {
        return;
    }

    const firstActiveView = layoutContainer.querySelector('.lm_active');
    if (!firstActiveView) {
        return;
    }

    const name = getViewNameFromTabId(firstActiveView.id);
    return { name, uuid: fin.me.uuid };
};

/**
 * Recursively clones a layout object, calling a passed callback on each `componentState` in the tree.
 * @param node Either the layout object itself, or one of the items in its tree.
 * @param callback Callback to be called on each component's `componentState`
 * @returns A mapped copy of the layout
 */
export const mapLayoutViewComponents = (node: any, callback: (arg0: any) => any) => {
    if (node.content) {
        // Recurse down tree to find view components
        return {
            ...node,
            content: node.content.map((contentItem: any) => mapLayoutViewComponents(contentItem, callback))
        };
    }
    return { ...node, componentState: callback(node.componentState) };
};

/**
 * Recursively clones a layout object, calling a passed async callback on each `componentState` in the tree.
 * @param node Either the layout object itself, or one of the items in its tree.
 * @param callback Async callback to be called on each component's `componentState`
 * @returns A Promise resolving to a mapped copy of the layout
 */
export const mapLayoutViewComponentsAsync = async (node: any, callback: (arg0: any) => Promise<any>): Promise<any> => {
    if (node.content) {
        // Recurse down tree to find view components
        const mappedContent = await Promise.all(
            node.content.map((contentItem: any) => mapLayoutViewComponentsAsync(contentItem, callback))
        );
        return {
            ...node,
            content: mappedContent
        };
    }
    return { ...node, componentState: await callback(node.componentState) };
};

/**
 * Copies the componentState and generates a name if it's not there
 * @param componentState view's componentState in the layout object, corresponds to View options
 * @returns A copy of the componentState with name filled in
 */
export const generateViewNameIfNotExists = <T extends { name?: string }>(
    componentState: T
): Omit<T, 'name'> & { name: string } => {
    componentState.name ||= `${VIEW_NAME_PREFIX}${randomUUID()}`;

    return componentState as T & { name: string };
};

export const generateViewNameAndIdentifierNameIfNotExists = <T extends { name?: string; _internalWorkspaceData: any }>(
    componentState: T
): T & { name?: string } => {
    return {
        ...componentState,
        name: componentState.name ? componentState.name : `internal-generated-view-${randomUUID()}`,
        _internalWorkspaceData: {
            ...componentState._internalWorkspaceData,
            viewIdentifier: componentState._internalWorkspaceData?.viewIdentifier || randomUUID()
        }
    };
};

const convertViewOptions = async (
    viewConfig: Partial<OpenFin.ViewOptions>,
    initViewOptions?: Partial<OpenFin.ViewOptions>
) => {
    return generateViewNameAndIdentifierNameIfNotExists(await applyViewDefaults(viewConfig, initViewOptions));
};

/**
 * Deep clones a layout and converts view options (add names if necessary, apply defaults).
 * @param layout The Layout to be cloned
 * @returns A Promise resolving to a copy of the layout with view options converted
 */
export const cloneLayoutAndConvertViewOptions = async (
    layout: PageLayout,
    initViewOptions?: Partial<OpenFin.ViewOptions>
): Promise<PageLayout> => {
    return mapLayoutViewComponentsAsync(cloneDeep(layout), (viewConfig) =>
        convertViewOptions(viewConfig, initViewOptions)
    );
};

export const cloneViewComponentWithoutName = (componentState: any) => ({
    ...componentState,
    name: undefined
});

/**
 * Deep clones a layout and removes view names.
 * @param layout The Layout to be cloned
 * @returns A copy of the layout with names removed
 */
export const cloneLayoutAndRemoveNames = (layout: PageLayout) => {
    const newLayout = { ...layout };
    return mapLayoutViewComponents(newLayout, cloneViewComponentWithoutName);
};

/**
 * Deep clones a layout and removes generated view names.
 * @param layout The Layout to be cloned
 * @returns A copy of the layout with generated names removed
 */
export const cloneLayoutAndRemoveGeneratedNames = (layout: PageLayout) => {
    const newLayout = { ...layout };
    return mapLayoutViewComponents(newLayout, (componentState) =>
        componentState.name && componentState.name.startsWith(VIEW_NAME_PREFIX)
            ? cloneViewComponentWithoutName(componentState)
            : componentState
    );
};

export const mapContentComponentState = (
    content: OpenFin.LayoutContent
): OpenFin.LayoutComponent['componentState'][] => {
    const componentStates: OpenFin.LayoutComponent['componentState'][] = [];
    (content && Array.isArray(content) ? content : []).forEach((item: any) => {
        if (item.type === 'component') {
            return componentStates.push(item.componentState);
        }
        const comps = mapContentComponentState(item.content);
        componentStates.push(...comps);
    });
    return componentStates;
};

export const getLayoutWithSingleView = async (
    title: string,
    url: string,
    winIdentity: OpenFin.Identity = currentOFIdentity
) => {
    let oldLayout;
    if (await isBrowserWindow(winIdentity)) {
        const options = await getOFWindow(winIdentity).getOptions();
        oldLayout = options.layout || { settings: {} };
    }

    return {
        ...oldLayout,
        content: [
            {
                type: 'stack',
                content: [
                    {
                        type: 'component',
                        componentName: 'view',
                        componentState: {
                            title,
                            url
                        }
                    }
                ]
            }
        ]
    };
};

export const layoutNameInitializedMap = new Map<string, boolean>();

export const isLayoutTabActive = (tabSelector: string) => {
    const element = document.getElementById(tabSelector);
    return element?.classList?.contains('lm_active');
};

const eventListeners: Map<LayoutDOMEventType, LayoutDOMEventListener[]> = new Map();

const propagateEvent = (ev: LayoutDOMEvent) => {
    const listeners = eventListeners.get(ev.type);
    if (listeners) {
        if ('detail' in ev) {
            Object.assign(ev, { isInitialized: !!layoutNameInitializedMap.get(ev.detail.originalElement.id) });
        }
        listeners.forEach((l) => l(ev));
    }
};
export const containerId = 'layout_container';
export const viewTabslistSelectors = '.lm_tabs';

export const addLayoutEventListener = (event: LayoutDOMEventType, listener: LayoutDOMEventListener) => {
    if (!eventListeners.has(event)) {
        eventListeners.set(event, []);
    }
    eventListeners.get(event).push(listener);
};

export const removeLayoutEventListener = (event: LayoutDOMEventType, listener: LayoutDOMEventListener) => {
    const listeners = eventListeners.get(event);
    if (listeners) {
        const index = listeners.indexOf(listener);
        if (index !== -1) {
            listeners.splice(index, 1);
        }
    }
};

const initContainerResizeObserver = (container: HTMLElement) => {
    const containerLayoutResizeObserver = new ResizeObserver(() => {
        propagateEvent({ type: 'container-resized' });
    });

    containerLayoutResizeObserver.observe(container);
};

type LayoutObserverCleanup = {
    viewItemContainerResizeObserver: ResizeObserver;
    tabListResizeObserver: ResizeObserver | null;
    containerCreatedHandler: (event: Event) => void;
    layoutContainer: Element;
};

// Store cleanup references for each layout by layoutName
const layoutObserverCleanupMap = new Map<string, LayoutObserverCleanup>();

/**
 * Cleans up ResizeObservers and event listeners for a specific layout.
 * Should be called when a layout is destroyed to prevent memory leaks.
 * @param layoutName The layoutName/layoutContainerKey to cleanup
 */
export const cleanupLayoutObservers = (layoutName: string) => {
    const cleanup = layoutObserverCleanupMap.get(layoutName);
    if (cleanup) {
        cleanup.viewItemContainerResizeObserver.disconnect();
        cleanup.tabListResizeObserver?.disconnect();
        cleanup.layoutContainer.removeEventListener('container-created', cleanup.containerCreatedHandler);
        layoutObserverCleanupMap.delete(layoutName);
    }
};

/**
 * Initializes all layout observers for a specific layout container.
 * Creates observers for view item containers and tab lists, storing them atomically
 * in the cleanup map to prevent race conditions.
 * @param layoutContainer The layout container element
 * @param layoutName The layout name/key for cleanup tracking
 */
const initLayoutObservers = (layoutContainer: Element, layoutName: string) => {
    // Create view item container resize observer
    // Observes .lm_item_container elements which resize when separators are dragged
    const debouncedPropagate = debounce(() => {
        propagateEvent({ type: 'view-container-resized' });
    }, 50);
    const viewItemContainerResizeObserver = new ResizeObserver(debouncedPropagate);

    // Track which elements are already being observed to avoid duplicates
    const observedElements = new WeakSet<Element>();

    const observeContainer = (container: Element) => {
        if (!observedElements.has(container)) {
            observedElements.add(container);
            viewItemContainerResizeObserver.observe(container);
        }
    };

    // Observe existing containers
    layoutContainer.querySelectorAll('.lm_item_container').forEach(observeContainer);

    // Listen for new containers created by OpenFin Layout
    // See: https://cdn.openfin.co/docs/javascript/stable/classes/OpenFin.Layout.html#container-created
    const containerCreatedHandler = (event: Event) => {
        const containerSelector = (event as CustomEvent<{ containerSelector: string }>).detail?.containerSelector;
        if (containerSelector) {
            const newContainer = document.getElementById(containerSelector);
            if (newContainer) {
                // The container element itself is the .lm_item_container
                const itemContainer = newContainer.closest('.lm_item_container') || newContainer;
                observeContainer(itemContainer);
            }
        }
    };
    layoutContainer.addEventListener('container-created', containerCreatedHandler);

    // Create tab list resize observer
    const viewTabsList = layoutContainer.querySelectorAll('.lm_tabs');
    let tabListResizeObserver: ResizeObserver | null = null;
    if (viewTabsList.length !== 0) {
        tabListResizeObserver = new ResizeObserver(() => {
            propagateEvent({ type: 'tabs-list-resized' });
        });
        viewTabsList.forEach((tabList) => tabListResizeObserver.observe(tabList));
    }

    // Store all cleanup references atomically in a single write operation
    layoutObserverCleanupMap.set(layoutName, {
        viewItemContainerResizeObserver,
        tabListResizeObserver,
        containerCreatedHandler,
        layoutContainer
    });
};

let layoutListenersInitialized = false;

/**
 * Initialize the layout for the current OF window.
 */
export const initLayoutListeners = async (): Promise<void> => {
    if (!isFin) {
        throw new Error('initLayoutListeners can only be used in an OpenFin env. Avoid using during pre-rendering.');
    }

    if (!layoutListenersInitialized) {
        try {
            layoutListenersInitialized = true;
            const container: any = document.getElementById(containerId);
            if (!container) {
                throw new Error(`Cannot find container with id ${containerId}`);
            }
            container.addEventListener('tab-created', propagateEvent);
            container.addEventListener('tab-closed', propagateEvent);

            initContainerResizeObserver(container);

            const win = getCurrentOFWindow();
            const listener = async (e: any): Promise<void> => {
                const layoutName = e.layoutIdentity.layoutName;
                layoutNameInitializedMap.set(layoutName, true);
                const layoutContainer: Element = document.getElementById(layoutName);
                if (!layoutContainer) {
                    logger.error('initLayoutListeners', 'Cannot find layout container', {
                        layoutName,
                        windowName: win.identity.name
                    });
                    return;
                }
                // Initialize all layout observers atomically
                initLayoutObservers(layoutContainer, layoutName);
            };
            win.addListener('layout-ready', listener);
        } catch (err) {
            logger.error('initLayoutListeners', 'Error binding layout', {
                error: err instanceof Error ? err.message : String(err),
                stack: err instanceof Error ? err.stack : undefined
            });
        }
    }
};

/**
 * Deep clones a layout and changes its settings to make it "locked".
 * @param layout The Layout to be locked
 * @returns A restricted copy of the layout
 */
export const getLockedPageLayout = (layout: PageLayout) => {
    const lockedLayout = mapLayoutViewComponents(layout, (componentState) => ({
        ...componentState,
        isClosable: false
    }));

    return {
        ...lockedLayout,
        settings: {
            ...lockedLayout?.settings,
            reorderEnabled: false,
            preventDragIn: true,
            preventDragOut: true,
            newTabButton: null,
            preventSplitterResize: true,
            showCloseIcon: false,
            showPopoutIcon: false
        }
    };
};

/**
 * Accepts a locked layout and an unlocked layout as a reference.
 * Takes the layout settings of the reference layout and merges them into the locked layout, thereby unlocking it.
 * @param lockedLayout The Layout to unlock
 * @param referenceUnlockedLayout The Layout to serve as a reference of an unlocked layout
 * @returns An unlocked version of the target layout
 */
export const getUnlockedLayout = (lockedLayout: PageLayout, referenceUnlockedLayout: PageLayout) => {
    const referenceLayoutComponentStates = mapContentComponentState(referenceUnlockedLayout.content);
    const layoutWithViewsClosable = mapLayoutViewComponents(lockedLayout, (componentState) => {
        const matchingViewInReferenceLayout = referenceLayoutComponentStates.find(
            (view) =>
                view._internalWorkspaceData?.viewIdentifier === componentState._internalWorkspaceData?.viewIdentifier
        );

        // set the value of isClosable to that in unlocked layout
        const isClosable = matchingViewInReferenceLayout
            ? (matchingViewInReferenceLayout as unknown as OpenFin.ViewCreationOptions).isClosable
            : componentState.isClosable;
        return {
            ...componentState,
            isClosable
        };
    });
    return { ...layoutWithViewsClosable, settings: referenceUnlockedLayout.settings };
};

/**
 * Replaces the layout of the window with the provided layout and adjusts it based on provided page's options
 * @param layout Layout with which to replace current window's layout
 * @param page Page object
 * @returns
 */
export const replaceLayout = async (layout: PageLayout, page: AttachedPage) => {
    const layoutManager = fin.Platform.Layout.getCurrentSync();
    const newLayout = page.isLocked ? getLockedPageLayout(layout) : layout;

    // On slow computers, layoutManager.replace sometimes never resolves
    // this **should** be fixed, but we're adding a timeout just in case
    // see https://github.com/openfin/workspace/pull/1594
    // and https://openfin.jira.com/browse/RUN-8560 for more information
    try {
        await awaitPromiseWithTimeout(
            layoutManager.replace(newLayout),
            5000,
            'Replace Layout Error: layoutManager.replace did not resolve in time'
        );
    } catch (err) {
        if (
            err instanceof Error &&
            err.message === 'Replace Layout Error: layoutManager.replace did not resolve in time'
        ) {
            logger.warn('replaceLayout', 'Layout manager replace timed out', {
                error: err.message
            });
        } else {
            throw err;
        }
    }
};

export const findViewInLayout = (node: any, viewId: OpenFin.Identity): any[] => {
    if (node?.content) {
        // Recurse down tree to find view components
        const states: any[] = [];
        node.content.forEach((item: any) => states.push(...findViewInLayout(item, viewId)));
        return states;
    } else if (node?.componentState && node.componentName === 'view') {
        if (node.componentState.name === viewId.name) {
            return [node.componentState];
        } else {
            return [];
        }
    } else {
        return [];
    }
};

/**
 * Calculates the total number of views in a given layout configuration.
 *
 * @param node - The layout configuration to traverse.
 * @returns The total number of views in the layout configuration.
 */
export const countViews = (node: OpenFin.LayoutContent): number => {
    if (node) {
        return mapContentComponentState(node).length;
    } else {
        return 0;
    }
};

export const getLayoutConfig = async (layoutContainerKey: string) => {
    const layout = fin.Platform.Layout.wrapSync({
        ...fin.me.identity,
        layoutName: layoutContainerKey
    });
    return layout.getConfig();
};

export const findPageForView = async (
    viewName: string,
    browserWindowIdentity?: WindowIdentity
): Promise<AttachedPage | undefined> => {
    const workspacePlatform = getCurrentSync();
    const pages = !browserWindowIdentity
        ? await workspacePlatform.Browser.getAllAttachedPages()
        : await getCurrentSync().Browser.wrapSync(browserWindowIdentity).getPages();
    for (const page of pages) {
        const views = findViewInLayout(page.layout, { uuid: currentOFIdentity.uuid, name: viewName });
        if (views && views.length > 0) {
            return page;
        }
    }
};

/**
 * Only show the view tab icon when not on the landing page
 */
export const hideFavIconForLandingPage = async (view: OpenFin.View, tab: HTMLElement) => {
    const hideFavIcon = ({ url }: { url: string }) => {
        const isLanding: boolean = isLandingPage(url);
        const tabIcon = tab.querySelector('.tab-icon') as HTMLImageElement;
        if (tabIcon) {
            tabIcon.style.display = isLanding ? 'none' : 'inherit';
        }
    };

    // When duplicating a page or calling addPage the URL is not yet set so we need this listener
    await view.once('url-changed', hideFavIcon);

    const info = await view.getInfo();
    if (info.url) {
        view.removeListener('url-changed', hideFavIcon);
        hideFavIcon({ url: info.url });
    }
};
