import makeGetChannelClient, { withDisconnectListener } from '@common/utils/channels';
import { isEnvLocal, workspaceProviderFallbackUrl, workspaceProviderFinsLink } from '@common/utils/env';
import { isWindowRunning, providerOFIdentity } from '@common/utils/window';

import { SearchAPIClientChannelClient } from '@common/api/protocol/shapes/search';
import { HOME_SEARCH_CHANNEL_NAME } from '@common/api/shapes/home';

import { getThemeStorageController } from '@client-platform/api/controllers/theme-storage-controller-store';
import { dispatchThemeToWorkspaceProvider } from '@client-platform/api/theming';

import type {
    WorkspaceAPIClientChannelClient,
    WorkspaceChannelProvider,
    WorkspaceComponentChannelClient
} from './shapes/workspace';

export type { WorkspaceAPIClientChannelClient, WorkspaceComponentChannelClient, WorkspaceChannelProvider };

/** The name of the channel for the centralized workspace protocol. */
export const channelName = '__of_workspace_protocol__' as const;

/**
 * Get a channel client for the centralized Workspace protocol.
 *
 * The channel client is automatically connected to the Workspace Provider,
 * in which acts as a centralized location for executing Workspace API logic.
 *
 * The channel client can execute remote procedures on the provider via its `dispatch` function.
 * A call to the `dispatch` function will block until the channel action has concluded execution
 * in the Workspace Provider's address space.
 * For a list of supported procedures, see the `WorkspaceChannelAction` enum.
 *
 * @returns the channel client for the centralized workspace protocol.
 */
const channelClient = makeGetChannelClient(channelName);
export const getChannelClient: () => Promise<WorkspaceComponentChannelClient> =
    channelClient as () => Promise<WorkspaceComponentChannelClient>;
export const getClientAPIChannelClient: () => Promise<WorkspaceAPIClientChannelClient> =
    channelClient as () => Promise<WorkspaceAPIClientChannelClient>;

const searchChannelClient = makeGetChannelClient(HOME_SEARCH_CHANNEL_NAME);
export const getSearchClientAPIChannelClient: () => Promise<withDisconnectListener<SearchAPIClientChannelClient>> =
    searchChannelClient as () => Promise<withDisconnectListener<SearchAPIClientChannelClient>>;

const isLaunchedViaLibQuery = 'isLaunchedViaLib';

/**
 * not needed for 12.6.x,  but need to be backwards compatible
 *
 */
const getProviderUrlWithParams = (url: string) => {
    const finsURL = new URL(url);
    finsURL.searchParams.append(isLaunchedViaLibQuery, 'true');
    return finsURL.toString();
};

/**
 * Launches the Workspace Provider.
 * If the Workspace Provider is already running, does nothing.
 */
export const launchProvider = async () => {
    const isProviderRunning = await isWindowRunning(providerOFIdentity);
    if (!isProviderRunning) {
        // TODO: Remove Windows user agent check if Mac ever gets an RVM.
        // If local development, will fallback such that localhost Workspace provider is launched instead.
        if (isEnvLocal || navigator.userAgent.indexOf('Win') === -1) {
            await fin.Application.startFromManifest(getProviderUrlWithParams(workspaceProviderFallbackUrl));
            return;
        }
        await fin.System.openUrlWithBrowser(getProviderUrlWithParams(workspaceProviderFinsLink));
    }
};

/**
 * Launches the Workspace provider if it is not running.
 * Then gets a Channel Client that is connected to the Workspace Provider.
 * @returns the Channel Client that is connected to the Workspace Provider.
 */
export const getChannelClientAndLaunchProvider = async () => {
    await launchProvider();
    return getChannelClient();
};

/**
 * Gets the theme data from the Platform provider, then launches the Workspace provider if it is not running, and then dispatches the theme data to the Workspace provider.
 * Then gets a Channel Client that is connected to the Workspace Provider.
 * @returns the Channel Client that is connected to the Workspace Provider.
 */
export const getChannelClientAndInitializeWorkspaceProvider = async () => {
    const themeStorageController = getThemeStorageController();
    const themePaletteSheet = themeStorageController.getThemePaletteSheet();
    const selectedScheme = themeStorageController.getScheme();
    const themePalette = themeStorageController.getThemePalette();

    await launchProvider();

    await dispatchThemeToWorkspaceProvider({ themePaletteSheet, selectedScheme, themePalette });

    return getClientAPIChannelClient();
};
