import workspacePerformance from '@common/utils/performance';
import { randomUUID } from '@common/utils/uuid';

export const browserWindowPerformanceMarkStart = (): string => {
    const uuid = randomUUID();
    const performanceMarkTitle = `browser-window-startup-${uuid}`;
    workspacePerformance.markStart(performanceMarkTitle);
    return performanceMarkTitle;
};

export const browserWindowPerformanceMarkAPIReturn = (performanceMarkTitle: string) => {
    workspacePerformance.markAndMeasure(`browser-window-started`, performanceMarkTitle);
};

export const setupBrowserWindowShownPerformanceMark = (performanceMarkTitle: string) => {
    const ofApp = fin.Application.wrapSync({ uuid: fin.me.identity.uuid });
    ofApp.once('window-shown', () => {
        workspacePerformance.markAndMeasure(`browser-window-shown`, performanceMarkTitle);
    });
};

export const contextMenuPerformanceMarkStart = () => {
    const uuid = randomUUID();
    const performanceMarkTitle = `browser-context-menu-startup-${uuid}`;
    workspacePerformance.markStart(performanceMarkTitle);
    return performanceMarkTitle;
};

export const contextMenuPerformanceMarkEnd = (performanceMarkTitle: string) => {
    workspacePerformance.markAndMeasure(`browser-context-menu-shown`, performanceMarkTitle);
};

export const contextMenuPerformanceMarkAPIReturn = (performanceMarkTitle: string) => {
    workspacePerformance.markAndMeasure(`browser-context-menu-called`, performanceMarkTitle);
};
export const setupContextMenuPerformanceMark = (performanceMarkTitle: string) => {
    const ofApp = fin.Application.wrapSync({ uuid: fin.me.identity.uuid });
    ofApp.once('window-shown', () => {
        contextMenuPerformanceMarkEnd(performanceMarkTitle);
    });
};
