const getCompleteColorSet = (set: NotificationIndicatorColorsSet) => {
    const { background, foreground } = set;
    return { background, foreground: foreground ?? '#FFFFFF' };
};

export const parseNotificationIndicatorColors = (customTheme: CustomTheme): NotificationIndicatorColorsParsed => {
    const indicatorColors = Object.keys(customTheme.notificationIndicatorColors ?? {});
    if (indicatorColors?.length) {
        const darkNotificationIndicatorColors: ThemeExtension['notificationIndicatorColors'] = {};
        const lightNotificationIndicatorColors: ThemeExtension['notificationIndicatorColors'] = {};

        indicatorColors.forEach((indicatorColor) => {
            const color = customTheme.notificationIndicatorColors[indicatorColor];

            if ('background' in color) {
                darkNotificationIndicatorColors[indicatorColor] = getCompleteColorSet(color);
                lightNotificationIndicatorColors[indicatorColor] = getCompleteColorSet(color);
            } else {
                darkNotificationIndicatorColors[indicatorColor] = getCompleteColorSet(color.dark ?? color.light);
                lightNotificationIndicatorColors[indicatorColor] = getCompleteColorSet(color.light ?? color.dark);
            }
        });

        return {
            light: lightNotificationIndicatorColors,
            dark: darkNotificationIndicatorColors
        };
    }
    return {
        light: null,
        dark: null
    };
};

export const constructThemePaletteSheet = (themes: GeneratedPalettes): string => {
    const lightVars = themes.light.toCSS();
    const darkVars = themes.dark.toCSS();

    return `:root{${lightVars}}
                [data-scheme="dark"] {
                    ${darkVars}
                }
                @media (prefers-color-scheme: dark) {
                    [data-scheme="system"] {${darkVars} }
                }

                @media (prefers-color-scheme: light) {
                    [data-scheme="system"] {${lightVars} }
                }
            `;
};

const getThemePaletteSheetFromPlatform = async (platformIdentity: OpenFin.Identity): Promise<string | undefined> => {
    try {
        const themePaletteSheet = await wrapSync(platformIdentity).Theme.getThemePaletteSheet();
        if (themePaletteSheet?.trim()) {
            return themePaletteSheet;
        }
    } catch (err) {
        logger.warn('getThemePaletteSheetFromPlatform', 'Theme API fallback failed', {
            error: err instanceof Error ? err.message : String(err)
        });
    }

    return undefined;
};

const getThemeData = async (
    platformIdentity: OpenFin.Identity
): Promise<{ themes: CustomThemes | GeneratedPalettes; selectedScheme: ColorSchemeOptionType }> => {
    // eslint-disable-next-line no-underscore-dangle
    const preloadedThemeData = (fin as any)?.__internal_?.initialOptions?.workspacePlatform
        ?._themeData as PreloadedThemeData;

    // Fetch using API if preloaded theme data isn't available or if getting theme for a different platform
    const shouldFetchFromPlatform = !preloadedThemeData || platformIdentity.uuid !== currentOFIdentity.uuid;

    if (shouldFetchFromPlatform) {
        if (!preloadedThemeData) {
            logger.info('getComputedTheme', 'Unable to find preloaded theme data, fetching from platform provider');
        }
        // theme data wasn't included as part of window creation on platform provider
        const generatedPalettes = await wrapSync(platformIdentity).Theme.getGeneratedPalettes();
        const selectedScheme = await wrapSync(platformIdentity).Theme.getSelectedScheme();
        return { themes: generatedPalettes, selectedScheme };
    }

    return preloadedThemeData;
};

export const getComputedPlatformTheme = async (platformIdentity: OpenFin.Identity) => {
    const themeData = await getThemeData(platformIdentity);
    const { themes: platformThemes, selectedScheme } = themeData;

    // Use preloaded sheet or construct from GeneratedPalettes
    let themePaletteSheet: string | undefined = (themeData as PreloadedThemeData).themePaletteSheet;

    if (!themePaletteSheet && platformThemes && 'dark' in platformThemes && 'light' in platformThemes) {
        const genPalettes = platformThemes as GeneratedPalettes;

        if (typeof genPalettes.dark?.toCSS === 'function' && typeof genPalettes.light?.toCSS === 'function') {
            themePaletteSheet = constructThemePaletteSheet(genPalettes);
        }
    }

    if (!themePaletteSheet) {
        const fetchedThemePaletteSheet = await getThemePaletteSheetFromPlatform(platformIdentity);
        if (fetchedThemePaletteSheet) {
            themePaletteSheet = fetchedThemePaletteSheet;
        }
    }

    return { theme: platformThemes, defaultScheme: selectedScheme, themePaletteSheet };
};

export const setSelectedScheme = async (ctx: ColorSchemeOptionType): Promise<void> => {
    const channel = await getChannelClient();
    channel.dispatch('set-selected-scheme', ctx);
};

export const getComputedScheme = async (identity?: OpenFin.Identity): Promise<Exclude<ColorSchemeType, 'system'>> => {
    const client = await getWorkspacePlatformChannelClient(identity || fin.me.identity);

    // Use the override to get the scheme
    const scheme = await client.dispatch(WorkspacePlatformChannelAction.GetSelectedScheme, undefined);

    if (scheme === ColorSchemeOptionType.System) {
        return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
    }
    return scheme;
};

export const getComputedBackgroundColor = async (platformIdentity: OpenFin.Identity): Promise<string> => {
    const generatedPalettes = await wrapSync(platformIdentity).Theme.getGeneratedPalettes();
    const computedScheme = await getComputedScheme(platformIdentity);

    const darkBackgroundColor = generatedPalettes.dark['color.role.background.1'];
    const lightBackgroundColor = generatedPalettes.light['color.role.background.1'];

    return computedScheme === ColorSchemeOptionType.Dark ? darkBackgroundColor : lightBackgroundColor;
};
