import type OpenFin from '@openfin/core';

import { createLogger } from '@common/utils/logger';
import { PositioningType } from '@common/utils/positioning';
import { getMonitorWindowMostOn } from '@common/utils/window';
import { getCenterFromBounds, getOFWindow } from '@common/utils/window';

import { IndicatorBounds, IndicatorOptions, ShowAtType, WindowSize } from './types';

const logger = createLogger('common.IndicatorBounds');

/**
 * Gets the bounds of the parent window, with fallback to provided bounds.
 */
export const getParentWindowBounds = async (
    parentWindow: OpenFin.Window | false,
    parentWindowBounds?: OpenFin.WindowBounds
): Promise<OpenFin.WindowBounds | undefined> => {
    try {
        return parentWindow ? await parentWindow.getBounds() : parentWindowBounds;
    } catch (e) {
        logger.warn('getParentWindowBounds', 'Failed to get parent window bounds', {
            error: e instanceof Error ? e.message : String(e)
        });
        return parentWindowBounds;
    }
};

/**
 * Checks if a window is maximized.
 */
export const isWindowMaximized = async (parentWindow: OpenFin.Window | false): Promise<boolean> => {
    try {
        return parentWindow ? (await parentWindow.getState()) === 'maximized' : false;
    } catch (e) {
        logger.warn('isWindowMaximized', 'Failed to get parent window state', {
            error: e instanceof Error ? e.message : String(e)
        });
        return false;
    }
};

/**
 * Returns the rectangle we should use as a reference when positioning a new window.
 * Falls back to the monitor’s available rectangle when:
 *   • the parent window is absent,
 *   • the parent window is maximized,
 *   • the caller explicitly requests maximize‑on‑screen.
 */
async function getReferenceBounds(
    parentWin: OpenFin.Window | false,
    parentBounds: OpenFin.WindowBounds | undefined,
    positioning?: PositioningType
): Promise<OpenFin.RectangleByEdgePositions> {
    // Decide up‑front whether we should anchor to a monitor instead of the parent bounds.
    const useMonitorBounds =
        !parentWin || positioning === PositioningType.RelativeToMonitor || (await isWindowMaximized(parentWin));

    if (useMonitorBounds) {
        // Helper: pick the correct monitor and return its usable rectangle.
        const monitorRect = async (): Promise<OpenFin.RectangleByEdgePositions> => {
            if (parentBounds) {
                // Use the monitor on which the parent window sits.
                return (await getMonitorWindowMostOn(parentBounds)).availableRect;
            }
            // Fall back to the primary monitor.
            return (await fin.System.getMonitorInfo()).primaryMonitor.availableRect;
        };

        return monitorRect();
    }
    // Convert WindowBounds to RectangleByEdgePositions for consistency
    return {
        left: parentBounds!.left,
        top: parentBounds!.top,
        right: parentBounds!.left + parentBounds!.width,
        bottom: parentBounds!.top + parentBounds!.height
    };
}

/**
 * Pure function – returns the final indicator rectangle, nothing else.
 */
export async function computeIndicatorBounds(
    identity: OpenFin.Identity | null | undefined,
    mySize: WindowSize,
    opts: IndicatorOptions
): Promise<IndicatorBounds> {
    const parentWin = identity ? getOFWindow(identity) : false;
    const parentBounds = await getParentWindowBounds(parentWin, opts.fallbackParentBounds);
    const refBounds = await getReferenceBounds(parentWin, parentBounds, opts.positioning);
    const refCenter = getCenterFromBounds(refBounds as OpenFin.WindowBounds);

    const verticalTop =
        opts.showAt === ShowAtType.Top
            ? refBounds.top + 20
            : opts.isEnterprise
            ? refBounds.bottom - 128
            : refBounds.bottom + 12;

    return {
        left: refCenter.left - mySize.width / 2,
        top: verticalTop,
        width: mySize.width,
        height: mySize.height
    };
}
