import {
    FontFamily,
    FontSize,
    FontWeight,
    IconSize,
    LineHeight,
    Palette,
    Radius,
    Shadow,
    Transition,
    Unit,
    UnitPx
} from '@openfin/ui-library';

import { ThemeExtension } from '@client-platform/index';

/**
 * Generates a styled-component theme with a palette which indirectly references CSS vars.
 *
 * This effectively turns the JSS palette into a constant value, where the only thing that changes during a
 * theme/scheme switch is the value of the CSS vars it points to.
 */
export const varBasedTheme = ({
    brand,
    notificationIndicatorColors
}: Pick<ThemeExtension, 'brand' | 'notificationIndicatorColors'>): ThemeExtension => ({
    brand,
    notificationIndicatorColors,
    fontSize: FontSize,
    fontFamily: FontFamily,
    fontWeight: FontWeight,
    iconSize: IconSize,
    lineHeight: LineHeight,
    px: UnitPx,
    radius: Radius,
    shadow: Shadow,
    transition: Transition,
    unit: Unit,
    palette: {
        ...(Object.keys(Palette).reduce(
            (result, color) => ({
                ...result,
                [color]: `var(--workspace-palette-${color})`
            }),
            {}
        ) as typeof Palette)
    }
});
