import type OpenFin from '@openfin/core';

import debounce from 'lodash.debounce';

import { getContextGroups, getViewContextGroupId, joinContextGroup, removeFromGroup } from '@common/utils/interop';
import { containerId } from '@common/utils/layout';
import { createLogger } from '@common/utils/logger';

import { getViewTabHat } from '@enterprise/components/LayoutContainer/utils';

const logger = createLogger('enterprise.colorLinking');

// These classes are applied to Golden Layout elements for color-linking styles.
export enum ColorLinkingUiClass {
    SHOW_INTEROP_GROUPS = 'showInteropGroups',
    HIGHLIGHT = 'highlight'
}

const GoldenLayoutSelector = {
    TAB_HAT_SELECTOR: '.lm_tab',
    ITEM_CONTAINER_SELECTOR: '.lm_item_container',
    LAYOUT_CONTAINER_ID: containerId
};

function getViewParent(viewIdentity: OpenFin.Identity): HTMLDivElement | null {
    if (!viewIdentity?.name) return null;
    const container = document.getElementById(`container-${viewIdentity.name}`);
    if (!container) return null;
    /* .lm_item_container should be container.parent, but searching for safety */
    return container.closest(GoldenLayoutSelector.ITEM_CONTAINER_SELECTOR) as HTMLDivElement | null;
}

// [EAR-16] - Updating to get name to use in aria label
async function getContextGroupColorDataById(groupId: string): Promise<OpenFin.ContextGroupInfo | undefined> {
    const contextGroups = await getContextGroups();
    const group = contextGroups.find((g) => g.id === groupId);
    return group;
}

export async function getContextGroupColorForView(
    viewIdentity: OpenFin.Identity
): Promise<OpenFin.DisplayMetadata | undefined> {
    const groupId = await getViewContextGroupId(viewIdentity);
    return groupId ? (await getContextGroupColorDataById(groupId))?.displayMetadata : undefined;
}

export async function isSameGroup(viewIdentity: OpenFin.Identity, groupId: string): Promise<boolean> {
    const viewGroup = await getViewContextGroupId(viewIdentity);
    return viewGroup === groupId;
}

export function findActiveLayout(layoutContainerKey: string) {
    const container = document.getElementById(layoutContainerKey);

    if (!container) {
        logger.warn('findActiveLayout', 'Could not find layout container', { layoutContainerKey });
        return null;
    }

    return container;
}

/*
 * Highlighting side effects
 */
function removeAllHighlightingFromActiveLayout(layoutContainerKey: string) {
    const layout = findActiveLayout(layoutContainerKey);
    // find all tab hats in active layout
    const tabHats = layout.querySelectorAll(GoldenLayoutSelector.TAB_HAT_SELECTOR);
    // find all item containers in active layout
    const itemContainers = layout.querySelectorAll(GoldenLayoutSelector.ITEM_CONTAINER_SELECTOR);
    // remove highlight class from all tab hats and containers within active layout
    tabHats.forEach((tab) => tab.classList.remove(ColorLinkingUiClass.HIGHLIGHT));
    itemContainers.forEach((c) => c.classList.remove(ColorLinkingUiClass.HIGHLIGHT));
}

export async function updateBorderColor(viewIdentity: OpenFin.Identity): Promise<void> {
    const parent = getViewParent(viewIdentity);
    const tabHat = getViewTabHat(viewIdentity.name);
    const contextGroup = await getContextGroupColorForView(viewIdentity);
    // Grabbing title to build the label
    if (parent) {
        parent.style.borderColor = contextGroup?.color ?? '';
    }
    if (tabHat) {
        const title = tabHat.querySelectorAll('.lm_title')[0].innerHTML;
        tabHat.style.borderColor = contextGroup?.color ?? '';
        tabHat.ariaLabel = contextGroup?.name ? `${title} view. Member of ${contextGroup.name} context group.` : null;
    }
}

// Debounced to prevent race conditions caused by some triggers (e.g. view-focused event).
// We only care about the trailing value
export const debouncedSetContextHighlighting = debounce(
    async function (ids: OpenFin.Identity[], layoutContainerKey: string): Promise<void> {
        // Must happen after the await, or timing issues can cause multiple views to show as focused
        removeAllHighlightingFromActiveLayout(layoutContainerKey);
        ids.forEach(async (viewId, _index) => {
            const parent = getViewParent(viewId);
            const tabHat = getViewTabHat(viewId.name);

            if (parent && tabHat) {
                // get tab title for use in aria label
                const title = tabHat.querySelectorAll('.lm_title')[0].innerHTML;
                tabHat.ariaLabel = `${title} view`;

                tabHat.classList.add(ColorLinkingUiClass.HIGHLIGHT);
            }
        });
    },
    100,
    { leading: false, trailing: true }
);

export async function showBorder(viewIdentity: OpenFin.Identity): Promise<void> {
    const tabHat = getViewTabHat(viewIdentity.name);
    const parent = getViewParent(viewIdentity);
    if (tabHat && parent) {
        tabHat.classList.add(ColorLinkingUiClass.HIGHLIGHT);
        parent.classList.add(ColorLinkingUiClass.HIGHLIGHT);
    }
}

export async function highlightAllInteropViews(): Promise<void> {
    const views = await (fin.me as OpenFin.Window).getCurrentViews();
    const colorPromises = views.map((v) => updateBorderColor(v.identity));
    await Promise.all(colorPromises);

    const container = document.getElementById(GoldenLayoutSelector.LAYOUT_CONTAINER_ID);
    container?.classList.add(ColorLinkingUiClass.SHOW_INTEROP_GROUPS);
}

export function removeInteropOutlines(): void {
    const container = document.getElementById(GoldenLayoutSelector.LAYOUT_CONTAINER_ID);
    container?.classList.remove(ColorLinkingUiClass.SHOW_INTEROP_GROUPS);
}

const updateAndShowBorders = async (views: OpenFin.Identity[]): Promise<void> => {
    await Promise.all(views.map(updateBorderColor));
    views.forEach(showBorder);
};

/**
 * Accepts a group of views and a channelId and updates group membership based on the following rules:
 * - If all selected views are a member of group, remove them.
 * - If one or more view is NOT a member of the group, add all to group.
 * @param views Array of view identities
 * @param channelId id of the channel for the group to be joined / removed from
 * @returns Promise<void>
 */
export const updateContextGroup = async (views: OpenFin.Identity[], channelId: string): Promise<void> => {
    if (!views.length) {
        return;
    }
    const isSameGroupResponses = await Promise.all(views.map((v) => isSameGroup(v, channelId)));
    const isAllSameGroup = isSameGroupResponses.every((bool) => bool);
    const callback = isAllSameGroup ? removeFromGroup : joinContextGroup;
    await Promise.all(views.map((v) => callback(v, channelId)));
    return updateAndShowBorders(views);
};
