import { createSlice, PayloadAction } from '@reduxjs/toolkit';

import { createLogger } from '@common/utils/logger';

const logger = createLogger('enterprise.viewTabIcons');

/**
 * @module viewTabIconSlice
 * @description
 * Redux slice for managing view tab icons and their loading states.
 * This slice tracks which views have active loading indicators (spinners)
 * and updates their visibility based on loading events.
 */
interface TabIconState {
    /**
     * Maps view names to their corresponding spinner element IDs.
     */
    spinnerIds: { [viewName: string]: string };
    /**
     * Stores the loading state for each view.
     */
    viewLoadingState: { [viewName: string]: { isLoading: boolean } };
}

// Initial state
const initialState: TabIconState = {
    spinnerIds: {},
    viewLoadingState: {}
};

/**
 * Slice for managing tab icons and their loading states.
 */
const viewTabIconSlice = createSlice({
    name: 'viewTabIcons',
    initialState,
    reducers: {
        /**
         * Associates a view with a spinner element and applies a loading class.
         *
         * @param state - The current state of the slice.
         * @param action - Payload containing the spinner element reference and view name.
         */
        addViewIcon: (state, action: PayloadAction<{ spinnerRef: string; viewName: string }>) => {
            const { spinnerRef, viewName } = action.payload;
            state.spinnerIds[viewName] = spinnerRef;
            const spinnerEl = document.getElementById(spinnerRef);
            spinnerEl?.parentElement.classList.add('content-loading');
        },
        /**
         * Marks a view as loading and updates the associated spinner element.
         *
         * @param state - The current state of the slice.
         * @param action - Payload containing the view name.
         */
        viewStartedLoading: (state, action: PayloadAction<{ viewName: string }>) => {
            const { viewName } = action.payload;
            state.viewLoadingState[viewName] = { isLoading: true };
            const spinnerId = state.spinnerIds[viewName];

            if (!spinnerId) {
                logger.warn('viewStartedLoading', 'No spinner ID found for view', { viewName });
                return;
            }

            const spinnerEl = document.getElementById(spinnerId);
            spinnerEl?.parentElement.classList.add('content-loading');
        },
        /**
         * Marks a view as no longer loading and removes the loading class.
         *
         * @param state - The current state of the slice.
         * @param action - Payload containing the view name.
         */
        viewStoppedLoading: (state, action: PayloadAction<{ viewName: string }>) => {
            const { viewName } = action.payload;
            const spinnerId = state.spinnerIds[viewName];
            if (!spinnerId) {
                logger.warn('viewStoppedLoading', 'No spinner ID found for view', { viewName });
                return;
            }

            const spinnerEl = document.getElementById(spinnerId);
            spinnerEl?.parentElement.classList.remove('content-loading');
        },
        /**
         * Removes the view and its associated state.
         *
         * @param state - The current state of the slice.
         * @param action - Payload containing the view name.
         */
        removeViewIcon: (state, action: PayloadAction<{ viewName: string }>) => {
            const { viewName } = action.payload;
            if (!state.spinnerIds[viewName] && !state.viewLoadingState[viewName]) {
                return;
            }
            delete state.spinnerIds[viewName];
            delete state.viewLoadingState[viewName];
        }
    }
});

export const { addViewIcon, viewStartedLoading, viewStoppedLoading, removeViewIcon } = viewTabIconSlice.actions;
export default viewTabIconSlice.reducer;
