import type OpenFin from '@openfin/core';

import {
    cloneLayoutAndRemoveGeneratedNames,
    cloneLayoutAndRemoveNames,
    cloneViewComponentWithoutName
} from '@common/utils/layout';
import { getMachineId, getMachineName } from '@common/utils/snapshot';
import { randomUUID } from '@common/utils/uuid';

import type { AttachedPage, Page, PageLayout, PageWithUpdatableRuntimeAttribs } from './shapes';

export function cleanPage<T extends AttachedPage | Page>(page: T): T {
    return {
        ...page,
        hasUnsavedChanges: undefined,
        parentIdentity: undefined,
        isActive: undefined,
        layout: cloneLayoutAndRemoveGeneratedNames(page.layout)
    };
}

/**
 * Get a page layout.
 * @param layout the layout to add details to.
 * @returns the layout with extra details.
 */
const getPageLayout = async (layout: PageLayout): Promise<PageLayout> => {
    const machineId: string = await getMachineId();
    const machineName: string = getMachineName();
    return {
        ...layout,
        layoutDetails: { machineId, machineName }
    } as PageLayout;
};

/**
 * Generates a Page object which represents a page.
 * @param title the title for the page.
 * @param layout the layout for the page.
 */
export const makePage = async (
    title: string,
    layout: OpenFin.LayoutOptions
): Promise<PageWithUpdatableRuntimeAttribs> => {
    const pageId = randomUUID();
    return {
        pageId,
        title,
        layout: await getPageLayout(layout),
        isReadOnly: false
    };
};

/**
 * Clone a page.
 * @param page the page to clone.
 * @returns a clone of the given page.
 */
export const clonePage = async <T extends Page | AttachedPage>(page: T): Promise<T> => {
    const pageMade = await makePage(page.title, cloneLayoutAndRemoveNames(page.layout));
    if (page.panels) {
        pageMade.panels = page.panels.map((panel) => ({
            ...panel,
            viewOptions: cloneViewComponentWithoutName(panel.viewOptions)
        }));
    }
    return {
        ...page,
        ...pageMade
    };
};
