export const printMenuOptions = async (isViewSelected: boolean): Promise<GlobalContextMenuItemTemplate> => {
    // KNOWN ISSUE: Printing Screenshot does not work for Mac users. Until this is fixed, we are removing the print screen option for Mac users.
    const isWindows = await isOSWindows();

    return {
        label: t('contextMenu.print'),
        submenu: [
            {
                type: MenuItemType.Label,
                label: t('contextMenu.submenu.print'),
                data: { type: GlobalContextMenuOptionType.Print },
                enabled: isViewSelected
            },
            {
                type: MenuItemType.Label,
                label: t('contextMenu.submenu.printAll'),
                data: { type: GlobalContextMenuOptionType.PrintAll }
            },
            ...(isWindows
                ? [
                      // TODO: remove cast once @openfin/core updates their types
                      Separator as GlobalContextMenuItemTemplate,
                      {
                          type: MenuItemType.Label,
                          label: t('contextMenu.printScreen'),
                          data: { type: GlobalContextMenuOptionType.PrintScreen }
                      }
                  ]
                : [])
        ],
        data: undefined
    };
};

