export const getSavedWorkspaceContextMenuOptions = (
    activeWorkspace: Workspace,
    savedWorkspaces: Pick<Workspace, 'workspaceId' | 'title'>[],
    contextMenuOptionType: GlobalContextMenuOptionType
) => {
    return savedWorkspaces.map((workspace) => {
        const isActive = workspace.workspaceId === activeWorkspace.workspaceId;
        return {
            label: workspace.title,
            type: MenuItemType.Checkbox,
            enabled: !isActive,
            checked: isActive,
            data: {
                type: contextMenuOptionType,
                workspaceId: workspace.workspaceId
            }
        };
    });
};

export const getAppearanceContextMenuOptions = async () => {
    const selectedScheme = await WP.getCurrentSync().Theme.getSelectedScheme();
    return [
        {
            label: t('theme.light'),
            type: MenuItemType.Checkbox,
            checked: selectedScheme === ColorSchemeOptionType.Light,
            data: {
                type: GlobalContextMenuOptionType.Appearance,
                scheme: ColorSchemeOptionType.Light
            }
        },
        {
            label: t('theme.dark'),
            type: MenuItemType.Checkbox,
            checked: selectedScheme === ColorSchemeOptionType.Dark,
            data: {
                type: GlobalContextMenuOptionType.Appearance,
                scheme: ColorSchemeOptionType.Dark
            }
        },
        {
            label: t('theme.system'),
            type: MenuItemType.Checkbox,
            checked: selectedScheme === ColorSchemeOptionType.System,
            data: {
                type: GlobalContextMenuOptionType.Appearance,
                scheme: ColorSchemeOptionType.System
            }
        }
    ];
};

export const getGlobalContextMenuTemplate = async (
    winIdentity: OpenFin.Identity,
    selectedViews: OpenFin.Identity[] = []
): Promise<GlobalContextMenuItemTemplate[]> => {
    const isStorefrontRunning = await isStorefrontWindowRunning();
    const { newPageUrl } = await getLandingPageUrls(winIdentity);
    const disableMultiplePages = await getDisableMultiplePagesOption(winIdentity);
    const isLocked = await getIsLockedOption(winIdentity);
    const isEnterprise = await isEnterpriseBrowser(winIdentity);
    const menuTemplate: GlobalContextMenuItemTemplate[] = [];
    const hasSelectedViews = selectedViews.length > 0;
    // Do not include a new window or new page option if there is no new page Url given
    if (newPageUrl) {
        menuTemplate.push(newWindow());
        // Do not include new page option if pages are disabled
        if (!disableMultiplePages) {
            menuTemplate.push(newPage(!isLocked, isEnterprise));
        }
    }
    // TODO: remove cast once @openfin/core updates their types
    menuTemplate.push(Separator as OpenFin.MenuItemTemplate<any>);

    const platform = WP.getCurrentSync();
    const isLegacySinglePaletteTheme = await platform.Theme.getIsLegacySinglePaletteTheme();
    const activeWorkspace = await platform.getCurrentWorkspace({ skipSnapshotUpdate: true });
    const savedWorkspaces = await platform.Storage.getWorkspacesMetadata();

    const lastSavedWorkspace = savedWorkspaces.find(
        (workspace) => workspace.workspaceId === activeWorkspace.workspaceId
    );

    // check window active page against stored pages

    const browserWindow = platform.Browser.wrapSync(winIdentity);
    const browserWindowPages = await browserWindow.getPages();
    const activePage = browserWindowPages.find((page) => page.isActive);
    const savedPage = activePage ? await platform.Storage.getPage(activePage.pageId) : false;

    // Enable 'Restore Last Saved Changes' if the active workspace is a saved workspace
    menuTemplate.push({
        ...restoreChanges(),
        enabled: !!lastSavedWorkspace
    });

    // Enabled 'Save Workspace' if the active workspace is a saved workspace
    menuTemplate.push({
        ...saveWorkspace(),
        enabled: !!lastSavedWorkspace
    });

    // Workspace save as is always enabled
    menuTemplate.push(saveWorkspaceAs());

    // Enable 'Rename' if the active workspace is a saved workspace
    menuTemplate.push({
        ...renameWorkspace(),
        enabled: !!lastSavedWorkspace
    });

    // Enable 'Switch' and 'Delete' if there exists at least one saved workspace that is not the currently active one
    if (savedWorkspaces.some((workspace) => workspace.workspaceId !== activeWorkspace.workspaceId)) {
        menuTemplate.push(
            {
                label: switchWorkspace().label,
                submenu: getSavedWorkspaceContextMenuOptions(
                    activeWorkspace,
                    savedWorkspaces,
                    GlobalContextMenuOptionType.SwitchWorkspace
                ),
                data: undefined
            },
            {
                label: deleteWorkspace().label,
                submenu: getSavedWorkspaceContextMenuOptions(
                    activeWorkspace,
                    savedWorkspaces,
                    GlobalContextMenuOptionType.DeleteWorkspace
                ),
                data: undefined
            }
        );
    } else {
        menuTemplate.push(
            {
                label: switchWorkspace().label,
                enabled: false,
                data: undefined
            },
            {
                label: deleteWorkspace().label,
                enabled: false,
                data: undefined
            }
        );
    }

    // Downloads option
    menuTemplate.push({
        label: downloads().label,
        data: {
            type: GlobalContextMenuOptionType.Downloads
        }
    });

    if (!isLegacySinglePaletteTheme) {
        menuTemplate.push({
            label: appearance().label,
            submenu: await getAppearanceContextMenuOptions(),
            data: undefined
        });
    }

    // Page options

    const savePageOption = {
        ...savePage(isEnterprise),
        enabled: !!savedPage
    };

    menuTemplate.push(
        // TODO: remove cast once @openfin/core updates their types
        Separator as OpenFin.MenuItemTemplate<any>,
        savePageOption,
        savePageAs(isEnterprise),
        await printMenuOptions(hasSelectedViews)
    );

    return isStorefrontRunning
        ? [...menuTemplate, ...menuTemplateWithStorefront()]
        : [...menuTemplate, ...menuTemplateWithoutStorefront()];
};
