import type OpenFin from '@openfin/core';

import { AttachedPageInternal } from '@common/api/pages/shapes';

import { getUnlockedLayout } from './layout';
import LocalStorageKey from './local-storage-key';

export type SnapshotDetailsExtended = OpenFin.Snapshot['snapshotDetails'] & {
    machineId: string;
    machineName?: string;
};

export type SnapshotExtended = OpenFin.Snapshot & {
    snapshotDetails: SnapshotDetailsExtended;
};

export type ApplySnapshotOptionsExtended = OpenFin.ApplySnapshotOptions & {
    attachToExistingWindow: boolean;
};

/**
 * Set a friendly name of the current machine.
 * @param name the friendly name.
 */
export function setMachineName(name: string) {
    localStorage.setItem(LocalStorageKey.MachineName, name);
}

/**
 * Get the machine's friendly name.
 * @returns the machine's friendly name.
 */
export function getMachineName() {
    return localStorage.getItem(LocalStorageKey.MachineName) ?? 'unknown';
}

/**
 * The current machine ID.
 */
let machineId: string;

/**
 * Get the current machine ID.
 * @returns the machine ID.
 */
export async function getMachineId() {
    if (!machineId) {
        machineId = await fin.System.getMachineId();
    }
    return machineId;
}

export const updateActivePage = (browserWindow: OpenFin.WindowOptions) => {
    if (
        Array.isArray(browserWindow.workspacePlatform?.pages) &&
        (browserWindow.layoutSnapshot || browserWindow.layout)
    ) {
        const activePage: AttachedPageInternal = browserWindow.workspacePlatform.pages.find(
            (p) => (p as AttachedPageInternal).isActive
        );
        if (activePage) {
            // Find the active page in the layoutSnapshot
            const activeLayout = browserWindow.layoutSnapshot
                ? browserWindow.layoutSnapshot.layouts[activePage.layoutContainerKey]
                : browserWindow.layout;
            if (activeLayout) {
                if ((activePage as AttachedPageInternal).isLocked) {
                    // browserWindow.layout has low-level settings specific to
                    // the locked state (e.g. can't close, rearrange views).
                    // activePage.layout will have unlocked settings provided by developer.
                    // We want the latter because we can compute the former from it (the inverse isn't true)
                    const unlockedLayout = getUnlockedLayout(activeLayout, activePage.layout);
                    activePage.layout = unlockedLayout;
                    browserWindow.layout = unlockedLayout;
                } else {
                    activePage.layout = activeLayout;
                    browserWindow.layout = activeLayout;
                }
            }
        }
    }

    return browserWindow;
};

/**
 * Get a snapshot with extra snapshot details.
 * @param snapshot the snapshot to extend.
 * @returns the snapshot with more snapshot details.
 */
export async function getSnapshotExtended(snapshot?: OpenFin.Snapshot): Promise<SnapshotExtended> {
    const targetSnapshot = snapshot || (await fin.Platform.getCurrentSync().getSnapshot());
    if ((targetSnapshot as SnapshotExtended).snapshotDetails?.machineId) {
        // If the snapshot is already extended at platform level, return.
        return targetSnapshot as SnapshotExtended;
    }

    const machineName = getMachineName();
    const newSnapshot = {
        ...targetSnapshot,
        snapshotDetails: {
            ...targetSnapshot.snapshotDetails,
            machineId: await getMachineId(),
            machineName
        }
    } as SnapshotExtended;
    return newSnapshot;
}
