import type OpenFin from '@openfin/core';

import { getEnterpriseBaseUrl } from '@common/utils/browser-base-url';
import makeGetChannelClient from '@common/utils/channels';
import { showChildWindow } from '@common/utils/menu-window-provider';
import { getCenterOfParentWindowMonitor } from '@common/utils/modal-bounds';
import PageRoute from '@common/utils/route';
import { getBoundsFromCenter, getCenterFromBounds, getOFWindow, WindowName } from '@common/utils/window';

import { EnterpriseRequestModalChannelAction } from '@common/api/protocol/browser';

import { AboutPageConfig, SendUpdateVersionModalResponsePayload } from '@client-platform/shapes';

let channelClient: Promise<OpenFin.ChannelClient> | undefined;

export const enterpriseModalChannelClient = () => {
    if (!channelClient) {
        channelClient = makeGetChannelClient(
            `${typeof fin !== 'undefined' && fin.me.identity.uuid}-enterprise-modal`
        )();
    }
    return channelClient;
};

export async function sendUpdateVersionModalResponse(payload: SendUpdateVersionModalResponsePayload): Promise<void> {
    const channel = await enterpriseModalChannelClient();
    return channel.dispatch(EnterpriseRequestModalChannelAction.SendUpdateVersionModalResponse, payload);
}

export const showAboutPagePopup = async (payload: AboutPageConfig) => {
    const urlSearchParams = new URLSearchParams({ ...payload, title: 'About' });
    const monitorCenter = await getCenterOfParentWindowMonitor(fin.me.identity);
    const defaultWidth = 360;
    const defaultHeight = payload.copyrightMessage ? 320 : 286;
    const bounds = getBoundsFromCenter(monitorCenter, { height: defaultHeight, width: defaultWidth });
    return showChildWindow({
        options: {
            frame: true,
            smallWindow: true,
            saveWindowState: false,
            showTaskbarIcon: true,
            includeInSnapshots: false,
            workspacePlatform: {
                // eslint-disable-next-line @typescript-eslint/ban-ts-comment
                // @ts-ignore
                windowType: 'enterprise'
            },
            resizable: false,
            name: WindowName.AboutPageWindow,
            url: (await getEnterpriseBaseUrl()) + PageRoute.EnterpriseAboutPage,
            defaultWidth,
            defaultHeight,
            preventBlur: true,
            ...bounds
        },
        parameters: urlSearchParams
    });
};

export const showDesktopSignalsModal = async (winIdentity: OpenFin.Identity) => {
    const parentWin = getOFWindow(winIdentity);
    const parentWindowBounds = await parentWin.getBounds();
    const targetCenter = getCenterFromBounds(parentWindowBounds);
    const defaultWidth = 432;
    const defaultHeight = 230;
    const bounds = getBoundsFromCenter(targetCenter, { height: defaultHeight, width: defaultWidth });

    return showChildWindow({
        options: {
            smallWindow: true,
            saveWindowState: false,
            showTaskbarIcon: true,
            includeInSnapshots: false,
            workspacePlatform: {
                windowType: 'enterprise'
            },
            resizable: false,
            name: WindowName.DesktopSignalsModal,
            url: (await getEnterpriseBaseUrl()) + PageRoute.DesktopSignalsModal,
            defaultWidth,
            defaultHeight,
            preventBlur: false,
            ...bounds
        },
        parameters: new URLSearchParams({ title: 'Desktop Signals Modal' })
    });
};
