export const capitalize = (s: string) => s.charAt(0).toUpperCase() + s.slice(1).toLowerCase();

export const pascalize = (s: string) => {
    let splitItems: string[] = [s];
    if (s.indexOf('-') !== -1 || s.indexOf(' ') !== -1 || s.indexOf('_') !== -1) {
        splitItems = s.replace(/ |-/g, '_').split('_');
    } else if (s.toUpperCase() !== s) {
        splitItems = (s.charAt(0).toUpperCase() + s.slice(1)).match(/[A-Z][a-z]+/g) ?? [];
    }
    return splitItems.map(capitalize).join('');
};

export const isStringMatchesQuery = (title: string, query = '') => {
    return title.toLowerCase().includes(query.toLowerCase());
};
