// we need bool for older client library versions
export type PlatFormSupportedFeatures =
    | boolean
    | {
          isWorkspacePlatform: boolean;
          isBrowserInitialized: boolean;
          analytics?: {
              isSupported: boolean;
          };
      };

export const getPlatformClient = async (identity: OpenFin.ApplicationIdentity): Promise<OpenFin.ChannelClient> => {
    const platform = fin.Platform.wrapSync(identity);
    return platform.getClient();
};

export const internalGetWorkspacePlatformChannelClient = async (
    identity: OpenFin.ApplicationIdentity
): Promise<PlatFormSupportedFeatures> => {
    const client = await getPlatformClient(identity);
    const targetNotWorkspaceErrorMessage =
        'Target is not a Workspace Platform. Target must call WorkspacePlatform.init';
    let response: PlatFormSupportedFeatures;

    try {
        response = await client.dispatch('isWorkspacePlatform');
    } catch (e) {
        throw new Error(targetNotWorkspaceErrorMessage);
    }

    // backwards compatibility for old workspace versions (pre v8)
    if (typeof response === 'boolean' && response) {
        logger.warn(
            'internalGetWorkspacePlatformChannelClient',
            'You are using an older version of the workspace platform. Please update your workspace platform.'
        );
        return response;
    }

    // For workspace versions (post + including v8)
    if (typeof response === 'object' && response.isWorkspacePlatform) {
        return response;
    }

    throw new Error(targetNotWorkspaceErrorMessage);
};

/**
 * Get a channel client for a specific Workspace platform.
 *
 * The channel client can execute remote procedures on the platform via its `dispatch` function.
 * A call to the `dispatch` function will block until the channel action has concluded execution
 * in the Workspace platform's address space.
 * For a list of supported procedures, see the `ChannelAction` enum.
 *
 * @returns the channel client for the Workspace platform.
 */
export const getWorkspacePlatformChannelClient = async (identity: OpenFin.ApplicationIdentity) => {
    await internalGetWorkspacePlatformChannelClient(identity);
    return getPlatformClient(identity);
};

/**
 * Get a channel client for a specific Workspace platform.
 *
 * Ensure that the channel is used within a platform with the browser
 *
 * @returns the channel client for the Workspace platform.
 */
export const getBrowserChannelClient = async (identity: OpenFin.ApplicationIdentity) => {
    const response = await internalGetWorkspacePlatformChannelClient(identity);
    const targetNotBrowserErrorMessage = 'Target is not a Browser-enabled Workspace Platform.';

    if (typeof response === 'object' && response?.isBrowserInitialized !== true) {
        throw new Error(targetNotBrowserErrorMessage);
    }

    return getPlatformClient(identity);
};
