import type OpenFin from '@openfin/core';

import { isEnterpriseBrowser } from '@common/utils/enterpriseBrowser';
import {
    appearance,
    findInPage,
    getAppearanceContextMenuOptions,
    getCloseWindow,
    getQuitPlatform,
    manageDesktopSignals,
    newPage,
    newWindow,
    savePage,
    savePageAs
} from '@common/utils/global-context-menu';
import { makeNewLandingPage } from '@common/utils/landing-page';
import { countViews } from '@common/utils/layout';

import { AttachedPageInternal } from '@common/api/pages/shapes';

import { addToChannel, removeFromChannel } from '@client-platform/api/context-menu/browser-viewtab-handler';
import { showDesktopSignalsModal } from '@client-platform/api/modal';

import { getCurrentSync } from '@client-platform/index';
import {
    BrowserWorkspacePlatformWindowOptions,
    EnterpriseMainContextMenuItemData,
    EnterpriseMainContextMenuItemTemplate,
    EnterpriseMainContextMenuOptionType,
    GlobalContextMenuOptionType,
    OpenGlobalContextMenuPayload
} from '@client-platform/shapes';

import { showFindInPageInTargetWindow } from './find-in-page/showFindInPageHandler';
import { MenuItemType } from './context-menu';

export const getEnterpriseContextMenuTemplate = async ({
    identity
}: {
    identity: OpenFin.Identity;
    selectedViews: OpenFin.Identity[];
}): Promise<EnterpriseMainContextMenuItemTemplate[]> => {
    const platform = getCurrentSync();
    const browser = platform.Browser.wrapSync(identity);
    const pages = await browser.getPages();
    const activePage: AttachedPageInternal = pages.find((page) => page.isActive);
    const savedPage = await platform.Storage.getPage(activePage.pageId);
    const enableSavePageOptions = countViews(activePage.layout.content) > 1;
    const isEnterprise = await isEnterpriseBrowser(identity);

    const win = fin.Window.wrapSync(identity);
    const windowOptions = await win.getOptions();
    const isFindInPageDisabled = !!(
        windowOptions.workspacePlatform as BrowserWorkspacePlatformWindowOptions | undefined
    )?.disableFindInPage;

    const savePageOption = { ...savePage(isEnterprise), enabled: !!savedPage };
    const savePageAsOption = { ...savePageAs(isEnterprise), enabled: enableSavePageOptions };
    const isLegacySinglePaletteTheme = await platform.Theme.getIsLegacySinglePaletteTheme();
    return [
        newWindow(),
        newPage(true, isEnterprise),
        {
            type: MenuItemType.Separator
        },
        savePageOption,
        savePageAsOption,
        {
            type: MenuItemType.Separator
        },
        manageDesktopSignals(),
        ...(isFindInPageDisabled ? [] : [findInPage()]),
        {
            type: MenuItemType.Separator
        },
        ...(isLegacySinglePaletteTheme
            ? []
            : [
                  {
                      type: MenuItemType.Submenu,
                      label: appearance().label,
                      submenu: await getAppearanceContextMenuOptions()
                  },
                  {
                      type: MenuItemType.Separator
                  }
              ]),
        getCloseWindow(),
        {
            type: MenuItemType.Separator
        },
        getQuitPlatform(true)
    ];
};

export const handleEnterpriseMenuResponse = async (
    data: EnterpriseMainContextMenuItemData,
    payload: OpenGlobalContextMenuPayload
): Promise<boolean> => {
    const winIdentity = payload.identity;
    const platform = getCurrentSync();
    const browser = platform.Browser.wrapSync(winIdentity);
    const pages = await browser.getPages();
    const activePage: AttachedPageInternal = pages.find((page) => page.isActive);

    const selectedViews = payload.selectedViews;
    switch (data?.type) {
        case EnterpriseMainContextMenuOptionType.Lock: {
            await browser.updatePage({
                pageId: activePage.pageId,
                page: {
                    isLocked: !activePage.isLocked
                }
            });
            break;
        }
        case EnterpriseMainContextMenuOptionType.AddToChanel: {
            if (data.option) {
                await addToChannel(winIdentity, data.option, selectedViews);
            } else if (data.option === null) {
                await removeFromChannel(winIdentity, selectedViews);
            }
            break;
        }
        case EnterpriseMainContextMenuOptionType.ManageDesktopSignals: {
            await showDesktopSignalsModal(winIdentity);
            break;
        }
        case EnterpriseMainContextMenuOptionType.FindInPage: {
            await showFindInPageInTargetWindow(winIdentity);
            break;
        }
        case GlobalContextMenuOptionType.NewWindow: {
            const landingPage = await makeNewLandingPage(winIdentity);
            await getCurrentSync().Browser.createWindow({
                workspacePlatform: {
                    pages: [landingPage],
                    // eslint-disable-next-line @typescript-eslint/ban-ts-comment
                    // @ts-ignore
                    windowType: 'enterprise'
                }
            });
            break;
        }
        case EnterpriseMainContextMenuOptionType.Pin: {
            const { alwaysOnTop } = await browser.openfinWindow.getOptions();
            await browser.openfinWindow.updateOptions({ alwaysOnTop: !alwaysOnTop });
            break;
        }
        default: {
            return false;
        }
    }
    return true;
};
