/**
 * Very smol util intended to be executed ASAP in HTML pages
 * to load and compute the value of theme palette variables from localstorage, and react to
 * any updates to their value.
 *
 * When ran before the first paint, this guarantees the first paint (and subsequent paints)
 * will use the correct palette when StorageThemeProvider is in use, eliminating all flicker.
 *
 * `themeLoader` is turned into a string and executed in a script tag — it cannot reference
 * module imports. Use the inline `log` helper (structured, delegates to console).
 */

type ComputedScheme = 'light' | 'dark';

export const themeLoader = (uuid: string, addListeners = true) => {
    const log = {
        debug(operation: string, message: string, data?: Record<string, unknown>) {
            if (typeof console !== 'undefined' && console.debug) {
                console.debug('[common.StorageThemeProvider.themeLoader]', operation, message, data);
            }
        },
        error(operation: string, message: string, data?: Record<string, unknown>) {
            if (typeof console !== 'undefined' && console.error) {
                console.error('[common.StorageThemeProvider.themeLoader]', operation, message, data);
            }
        }
    };

    const themeSheet = localStorage.getItem(`${uuid}-ThemePaletteSheet`);
    log.debug('themeLoader', 'Theme sheet found in localStorage', { themeSheet });

    const sheet = new CSSStyleSheet();

    const applyCSS = (css: string) => {
        log.debug('applyCSS', 'Applying CSS', { css });
        const trimmedCSS = css.trim();
        document.adoptedStyleSheets = [...document.adoptedStyleSheets, sheet];
        sheet.replaceSync(trimmedCSS);
    };

    if (!themeSheet) {
        log.error('themeLoader', 'No theme sheet found in localStorage', {});
        return;
    }
    applyCSS(themeSheet);

    const schemeKey = `${uuid}-SelectedColorScheme`;
    const computeScheme = (): ComputedScheme => {
        const savedScheme = localStorage.getItem(schemeKey) as ComputedScheme;
        const savedDefaultScheme = localStorage.getItem(`${uuid}-ThemePaletteDefaultScheme`) as ComputedScheme;

        const systemPrefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
        const systemPreferredScheme = systemPrefersDark ? 'dark' : 'light';

        // pick the savedScheme, fallback to either default or system preference
        return savedScheme ?? savedDefaultScheme ?? systemPreferredScheme;
    };

    if (addListeners) {
        window.addEventListener('storage', (e): void => {
            if (e.key && e.key === `${uuid}-ThemePaletteSheet` && e.newValue) {
                try {
                    log.debug('storage', 'Theme sheet updated', { newValue: e.newValue });
                    sheet.replace(e.newValue);
                    if (typeof window !== 'undefined' && window.console) {
                        log.debug('storage', 'Theme stylesheet updated', {});
                    }
                } catch (err) {
                    log.error('storage', 'Failed to update theme stylesheet', {
                        error: err instanceof Error ? err.message : String(err)
                    });
                }
            }

            if (e.key && e.key === schemeKey && e.newValue) {
                const computedScheme = computeScheme();
                window.document.documentElement.setAttribute('data-scheme', computedScheme);
            }
        });

        window.matchMedia('(prefers-color-scheme: dark)').addEventListener('change', () => {
            const computedScheme = computeScheme();
            window.document.documentElement.setAttribute('data-scheme', computedScheme);
        });
    }

    const initialScheme = computeScheme();
    window.document.documentElement.setAttribute('data-scheme', initialScheme);
};
