import { workspaceBuildVersion, workspaceCdnEnvUrl } from '@common/utils/env';
import { createLogger } from '@common/utils/logger';
import Route from '@common/utils/route';

import { getOverrides } from '@common/api/overrides';

const logger = createLogger('common.browserBaseUrl');

let localBrowserUrl: string | undefined;

export function setLocalBrowserUrl(url: string) {
    localBrowserUrl = url;
}

export const removeTrailingSlash = (url: string) => url.replace(/\/$/, '');
/**
 * Get the base url override if it exists
 *
 * @returns The base url override if it exists, otherwise null
 */
export async function getBaseUrl(): Promise<string> {
    const browserOverrideBaseUrl = (await getOverrides()).browserBaseUrl;

    if (browserOverrideBaseUrl) {
        try {
            const url = new URL(browserOverrideBaseUrl);

            // remove the trailing slash if it exists
            if (url.pathname.endsWith('/')) {
                url.pathname = removeTrailingSlash(url.pathname);
            }

            // Local dev: accept origin-only or root path (e.g. http://localhost:4200) so browser loads on correct port
            if (url.pathname === '' || url.pathname === '/') {
                return removeTrailingSlash(browserOverrideBaseUrl);
            }

            // CDN/prod: path must be /workspace, then append version
            if (url.pathname === '/workspace') {
                url.pathname += `/${workspaceBuildVersion}`;
                return url.toString();
            }

            // Other paths: invalid
            logger.warn('getBaseUrl', 'browserOverrideBaseUrl must be a valid url with path /workspace', {
                browserOverrideBaseUrl
            });
        } catch (e) {
            logger.warn('getBaseUrl', 'browserOverrideBaseUrl must be a valid url', { browserOverrideBaseUrl });
        }
    }

    return localBrowserUrl ?? workspaceCdnEnvUrl;
}

/**
 * Get the browser base url
 * @param returnUrlWithATrailingSlash - if true, the url is returned with a trailing slash, if false it is not.
 * @returns The browser base url override if it exists, otherwise null
 */
export async function getBrowserBaseUrl(returnUrlWithATrailingSlash = false): Promise<string> {
    const url = (await getBaseUrl()) + Route.Browser;
    return returnUrlWithATrailingSlash ? url : removeTrailingSlash(url);
}

/**
 * Get the enterprise browser base url
 * @param returnUrlWithATrailingSlash - if true, the url is returned with a trailing slash, if false it is not.
 * @returns The browser base url override if it exists, otherwise null
 */
export async function getEnterpriseBaseUrl(returnUrlWithATrailingSlash = false): Promise<string> {
    const url = (await getBaseUrl()) + Route.EnterpriseBrowser;
    return returnUrlWithATrailingSlash ? url : removeTrailingSlash(url);
}

/**
 * @returns The default enterprise landing url
 */
export async function getEnterpriseLandingUrl(): Promise<string> {
    const supertabsOverride = localStorage.getItem('here-supertabs-api.landingUrl');
    if (supertabsOverride?.length) {
        return supertabsOverride;
    }
    return (await getEnterpriseBaseUrl()) + '/landing/';
}

/**
 * Get the enterprise browser or the workspace browser base url
 * @param isEnterprise - if true, we are in enterprise browser
 * @param returnUrlWithATrailingSlash - if true, the url is returned with a trailing slash, if false it is not.
 * @returns The browser base url override if it exists, otherwise null
 */
export const getDefaultBrowserUrl = async (isEnterprise: boolean, returnUrlWithATrailingSlash = false) => {
    return isEnterprise
        ? getEnterpriseBaseUrl(returnUrlWithATrailingSlash)
        : getBrowserBaseUrl(returnUrlWithATrailingSlash);
};
