import { createSlice } from '@reduxjs/toolkit';

import { currentOFIdentity } from '@common/utils/window';

import type { AttachedPageInternal } from '@common/api/pages/enterprise-shapes';

export interface AttachedPagesRootState {
    attachedPages: {
        activePageIndex: number;
        attachedPages: AttachedPageInternal[];
        isActivePageChanging: boolean;
        isInitialized: boolean;
    };
}

interface Action<P> {
    type: string;
    payload: P;
}

interface UpdatePageAtIndexPayload {
    index: number;
    page: Partial<AttachedPageInternal>;
}

/**
 * The source of truth for the current Browser window's attached page state.
 */
export const attachedPagesSlice = createSlice({
    name: 'attached-pages',
    initialState: {
        activePageIndex: 0,
        attachedPages: [],
        isActivePageChanging: false,
        isInitialized: false
    } as AttachedPagesRootState['attachedPages'],
    reducers: {
        setPages: (state, action: Action<AttachedPageInternal[]>) => {
            const pages = action.payload;

            state.attachedPages = (pages || []).map((page) => ({
                ...page,
                parentIdentity: currentOFIdentity
            }));

            const index = pages.findIndex(({ isActive }) => isActive);
            state.activePageIndex = index === -1 ? 0 : index;
        },
        updatePageAtIndex: (state, action: Action<UpdatePageAtIndexPayload>) => {
            const { index, page } = action.payload;
            const currentPageState = state.attachedPages[index];

            if (currentPageState) {
                state.attachedPages[index] = { ...currentPageState, ...page };
            }

            if (page.isActive) {
                const currActivePage = state.attachedPages[state.activePageIndex];
                if (currActivePage && index !== state.activePageIndex) {
                    currActivePage.isActive = false;
                }
                state.activePageIndex = index;
            }
        },
        setIsActivePageChanging: (state, action: Action<boolean>) => {
            state.isActivePageChanging = action.payload;
        },
        setIsInitialized: (state, action: Action<boolean>) => {
            state.isInitialized = action.payload;
        }
    }
});

export const { setPages, updatePageAtIndex, setIsActivePageChanging, setIsInitialized } = attachedPagesSlice.actions;

export const selectActivePageIndex = (state: AttachedPagesRootState): number => state.attachedPages.activePageIndex;

// TODO: remove the || {} return value and ensure callers are checking the result explicitly
export const selectActivePage = (state: AttachedPagesRootState): AttachedPageInternal =>
    state.attachedPages.attachedPages[selectActivePageIndex(state)] || ({} as AttachedPageInternal);

// TODO: remove the || {} return value and ensure callers are checking the result explicitly
export const selectPage = (state: AttachedPagesRootState, pageId: string): AttachedPageInternal =>
    state.attachedPages.attachedPages.find((page) => page.pageId === pageId) || ({} as AttachedPageInternal);

// TODO: remove the || {} return value and ensure callers are checking the result explicitly
export const selectPageByLayoutContainerKey = (
    state: AttachedPagesRootState,
    layoutContainerKey: string
): AttachedPageInternal =>
    state.attachedPages.attachedPages.find((page) => page.layoutContainerKey === layoutContainerKey) ||
    ({} as AttachedPageInternal);

export const selectPageWithIndex = (
    state: AttachedPagesRootState,
    pageId: string
): [AttachedPageInternal | undefined, number] => {
    const foundIndex = state.attachedPages.attachedPages.findIndex((page) => page.pageId === pageId);
    return [state.attachedPages.attachedPages[foundIndex], foundIndex];
};

export const selectPages = (state: AttachedPagesRootState): AttachedPageInternal[] => state.attachedPages.attachedPages;

export const selectIsActivePageChanging = (state: AttachedPagesRootState): boolean =>
    state.attachedPages.isActivePageChanging;

export const selectIsInitialized = (state: AttachedPagesRootState): boolean => state.attachedPages.isInitialized;

export default attachedPagesSlice.reducer;
