import Router from 'next/router';

import Route from '@common/utils/route';
function removeTrailingSlash(str: string) {
    return str.endsWith('/') ? str.slice(0, -1) : str;
}

export const getEnterpriseBaseUrlFromHref = (locationHref: string): string => {
    const basePath = removeTrailingSlash(Route.EnterpriseBrowser);
    const currentPath = Router.pathname;
    const currentUrl = new URL(locationHref);
    const pathName = currentUrl.pathname;
    // If current page does not have a trailing slash and router reports it with one, handle that.
    const currentRelativePath = removeTrailingSlash(basePath + currentPath);

    // pathname doesn't contain protocol or query params
    const baseUrl = pathName.substring(0, pathName.lastIndexOf(currentRelativePath));
    // remave trailing slash, because URL appends it if url is root of domain
    return removeTrailingSlash(new URL(baseUrl, currentUrl.origin).toString());
};
