import type PageRoute from '@common/utils/route';

import { isWindowDefined } from '../env';

/**
 * Multiple different Next projects can be merged together into one using zones.
 * This is the path prefix to a single one of those deployed projects.
 * More information can be found here:
 * https://nextjs.org/docs/advanced-features/multi-zones
 */
export enum Zone {
    Home = '/home',
    Browser = '/browser',
    Enterprise = '/enterprise',
    Provider = '/provider',
    Storefront = '/storefront',
    Dock = '/dock'
}

/**
 * The sub path that contains a single deployment of the frontend assets.
 *
 * This will be stripped out from the base path when using a `Route`.
 */
declare const ROUTER_ZONE: Zone;

/**
 * The full path prefix to the frontend assets.
 * The `ROUTER_ZONE` is the postfix of the `ROUTER_BASE_PATH`.
 */
declare const ROUTER_BASE_PATH: string;

/**
 * The full path prefix to the static frontend assets.
 * (Images, icons, fonts, etc.)
 */
declare const ROUTER_ASSETS_PATH: string;

const routerAssetsPath = typeof ROUTER_ASSETS_PATH !== 'undefined' ? ROUTER_ASSETS_PATH : '';
const routerBasePath = typeof ROUTER_BASE_PATH !== 'undefined' ? ROUTER_BASE_PATH : '';
const routerZone = typeof ROUTER_ZONE !== 'undefined' ? ROUTER_ZONE : '';

export function getRouterZone() {
    return routerZone;
}

/**
 * Gets the router's base path with the zone stripped out.
 */
export function getBasePathWithoutZone() {
    return routerBasePath.substring(0, routerBasePath.length - routerZone.length);
}

/**
 * Get the router path to assets like images, json, svg, etc.
 * @returns the path to the
 */
export function getAssetPath(route: string) {
    return routerAssetsPath + route;
}

/**
 * Gets the route without the zone prefix.
 * @param route the route to remove the zone prefix from.
 * @returns the route without the zone.
 */
export function getRouteWithoutZone(route: PageRoute | string): string {
    let routeWithoutZone = route;
    if (routeWithoutZone.startsWith(routerZone)) {
        routeWithoutZone = routeWithoutZone.substring(routerZone.length);
    }
    return routeWithoutZone;
}

/**
 * Get the absolute base path of the window with the zone stripped out.
 */
function getAbsoluteBasePathWithoutZone() {
    if (!window) {
        throw new Error('getAbsoluteBasePath can only be used in a window');
    }
    return `${window.origin}${getBasePathWithoutZone()}`;
}

/**
 * Get the absolute path to the route.
 */
export function getAbsoluteRoutePath(route: PageRoute | string) {
    if (!isWindowDefined) {
        throw new Error('getAbsoluteRoutePath can only be used in a window');
    }
    return getAbsoluteBasePathWithoutZone() + route;
}

/**
 * Get the base path of the router.
 * The base path of the router contains the router's zone as a postfix.
 */
export function getBasePath() {
    return routerBasePath;
}

/*
 * If the path is relative, it will be converted to an absolute path.
 * Otherwise, it will be returned unchanged.
 * @param path the path to make absolute.
 * @param baseUrl the base URL to use for the path. If not provided, the current location will be used. (Added for testing purposes)
 * @returns the absolute path.
 */
export function resolveAbsolutePath(path: string, baseUrl?: URL) {
    if (!isWindowDefined) {
        throw new Error('resolveAbsolutePath can only be used in a window');
    }
    const currentLocation = baseUrl ?? window.location;
    // Check if the URL is already absolute (starts with a protocol like "http://" or "https://" or "openfin://")
    if (/^(?:[a-z]+:)?\/\//i.test(path)) {
        return path; // Already absolute, return as is
    }

    // When using a custom protocol like "openfin://", URL.origin will be "null"
    const expectedOrigin = `${currentLocation.protocol}//${currentLocation.hostname}`;

    // If not absolute, construct the absolute URL using the current page's origin
    return new URL(path, expectedOrigin).href;
}

/**
 * Gets the path to the route with the router's base path.
 * @param route the route.
 * @returns the route with the router's base path.
 */
export function getRoutePath(route: PageRoute) {
    return `${getBasePathWithoutZone()}${route}`;
}

/**
 * Concatenates a specified origin URL with a specified path.
 * @returns the origin concatenated with the specified path.
 */
export function getOriginWithPath(origin: string, path: string) {
    const originWithoutSlash = origin.endsWith('/') ? origin.substring(0, origin.length - 1) : origin;
    const pathWithoutSlash = path.startsWith('/') ? path.substring(1) : path;
    return `${originWithoutSlash}/${pathWithoutSlash}`;
}

/**
 * Read query parameters of current window location.
 * @returns the query parameters.
 */
export function getQuery(): URLSearchParams {
    if (!isWindowDefined) {
        throw new Error('getQuery can only be used in a window');
    }
    return new URLSearchParams(window.location.search);
}

export const getUrlParams = (path: string) => {
    return Object.fromEntries(new URLSearchParams(path.substring(path.indexOf('#') + 1)));
};

export function getPathnameWithBasePath(pathname: string): string {
    let fullPath = pathname;
    if (!fullPath.startsWith(routerBasePath)) {
        fullPath = routerBasePath + fullPath;
    }
    if (!fullPath.endsWith('/')) {
        fullPath += '/';
    }
    return fullPath;
}

/**
 * Get the current route.
 * @returns
 */
export function getCurrentRoute(): PageRoute {
    if (!isWindowDefined) {
        throw new Error('getCurrentRoute can only be used in a window');
    }
    const basePathWithoutZone = getBasePathWithoutZone();
    return window.location.pathname.substring(basePathWithoutZone.length) as PageRoute;
}
