import { createSlice, PayloadAction } from '@reduxjs/toolkit';

export type FindInPageContentViewState = {
    currentResultIndex?: number | null;
    totalResults?: number | null;
    isVisible: boolean;
    value?: string | null;
};

export interface FindInPageRootState {
    findInPage: {
        activeContentViewName: string | null;
        contentViewStates: Record<string, FindInPageContentViewState>;
    };
}

export const findInPageSlice = createSlice({
    name: 'findInPage',
    initialState: {
        activeContentViewName: null,
        contentViewStates: {}
    } as FindInPageRootState['findInPage'],
    reducers: {
        // Set the active content view name (null to clear)
        setActiveContentViewName: (state, action: PayloadAction<string | null>) => {
            state.activeContentViewName = action.payload;
        },
        // Set entire state for a view (replaces existing state)
        setContentViewState: (
            state,
            action: PayloadAction<{ viewName: string; state: FindInPageContentViewState }>
        ) => {
            state.contentViewStates[action.payload.viewName] = action.payload.state;
        },
        // Update partial state for a view (merges with existing state)
        updateContentViewState: (
            state,
            action: PayloadAction<{ viewName: string; state: Partial<FindInPageContentViewState> }>
        ) => {
            const { viewName, state: viewState } = action.payload;
            state.contentViewStates[viewName] = {
                isVisible: false, // Default for required field
                ...state.contentViewStates[viewName],
                ...viewState
            };
        },
        // Delete state for a view
        deleteContentViewState: (state, action: PayloadAction<string>) => {
            delete state.contentViewStates[action.payload];
        }
    }
});

export const { deleteContentViewState, setActiveContentViewName, setContentViewState, updateContentViewState } =
    findInPageSlice.actions;

// Get the active content view name
export const selectActiveContentViewName = (state: FindInPageRootState): string | null =>
    state.findInPage.activeContentViewName;

// Get the visibility state for the active content view
export const selectActiveContentViewVisibility = (state: FindInPageRootState): boolean => {
    const activeViewName = state.findInPage.activeContentViewName;
    return activeViewName ? state.findInPage.contentViewStates[activeViewName]?.isVisible ?? false : false;
};

// Get the search value for the active content view
export const selectActiveContentViewFindInPageValue = (state: FindInPageRootState): string | null | undefined => {
    const activeViewName = state.findInPage.activeContentViewName;
    return activeViewName ? state.findInPage.contentViewStates[activeViewName]?.value : undefined;
};

// Get the current result index and total results for the active content view
export const selectActiveContentViewResultCounts = (
    state: FindInPageRootState
): {
    currentResultIndex?: number;
    totalResults?: number;
} => {
    const activeViewName = selectActiveContentViewName(state);
    if (!activeViewName) {
        return { currentResultIndex: undefined, totalResults: undefined };
    }
    const viewState = state.findInPage.contentViewStates[activeViewName];
    return {
        currentResultIndex: viewState?.currentResultIndex,
        totalResults: viewState?.totalResults
    };
};

export default findInPageSlice.reducer;
