import type OpenFin from '@openfin/core';

/* eslint-disable no-underscore-dangle */
import { finName, isFin } from './env';
import { log } from './logger';
import { currentOFIdentity, getCurrentOFWindow, isWindowRunning } from './window';

interface InternalWindowOptions extends OpenFin.PlatformWindowCreationOptions {
    workspacePlatform: OpenFin.WindowOptions['workspacePlatform'] & {
        _internalDeferShowOptions?: {
            setAsForeground?: boolean; // True if the window should be focused when shown
            autoShow?: boolean; // True if the window should auto show.
            deferShowEnabled?: boolean; // True if auto show is deferred to the window's javascript execution.
        };
    };
}

/**
 * This function prevents a created window from being auto shown by the Core.
 * The Core will auto show the window before the window has a chance to register a listener to prevent it.
 * With these options applied, the window must call `setCanShow(true)` when it is ready to be shown.
 * If `autoShow` was originally true, the window will be show upon the first call to `setCanShow(true)`.
 *
 * By applying these options it is assumed that the window calls `registerDeferShow()` and `setCanShow(true)`.
 *
 * This function should be used in conjunction the `withDeferShow` platform middleware.
 * `withDeferShow` will prevent the window from being shown before the window has launched and registered
 * its show requested listener.
 *
 * @param opts the options to modify.
 * @param setAsForeground the option to focus the window when it is shown
 * @returns the modified options.
 */
export const applyDeferShowOptions = <T>(opts: T, setAsForeground?: boolean): InternalWindowOptions & T => {
    const internalOpts = opts as InternalWindowOptions & T;
    if (!internalOpts.workspacePlatform) {
        internalOpts.workspacePlatform = {} as any;
    }

    internalOpts.workspacePlatform._internalDeferShowOptions = {
        setAsForeground: !!setAsForeground,
        deferShowEnabled: true,
        autoShow:
            internalOpts.workspacePlatform?._internalAutoShow ||
            internalOpts.workspacePlatform?._internalDeferShowOptions?.autoShow ||
            internalOpts.autoShow === undefined ||
            internalOpts.autoShow
    };

    internalOpts.autoShow = false;

    return internalOpts;
};

/**
 * This function is a middleware that can be applied to a platform's `createWindow` function.
 * If the defer show API has been enabled in window options using the `applyDeferShowOptions` function
 * the window will be prevented from showing.
 * @param superCreateWindow the create window method to decorate.
 * @returns the `createWindow` method wrapped with this middleware.
 */
export const withDeferShow =
    (
        superCreateWindow: (
            opts: OpenFin.PlatformWindowCreationOptions,
            callerIdentity: OpenFin.Identity
        ) => Promise<OpenFin.Window>
    ) =>
    async (opts: OpenFin.PlatformWindowCreationOptions, callerIdentity: OpenFin.Identity) => {
        let changed = false;

        const win = await superCreateWindow(opts, callerIdentity);
        if (!(opts as InternalWindowOptions)?.workspacePlatform?._internalDeferShowOptions?.deferShowEnabled) {
            return win;
        }

        const showRequestedListener = async () => {
            if (changed) return;
            const currentOptions = (await win.getOptions()) as InternalWindowOptions;
            await win.updateOptions({
                workspacePlatform: {
                    ...currentOptions.workspacePlatform,
                    _internalDeferShowOptions: {
                        ...currentOptions.workspacePlatform._internalDeferShowOptions,
                        autoShow: true
                    }
                }
            } as InternalWindowOptions);
            changed = true;
        };
        await win.addListener('show-requested', showRequestedListener);
        return win;
    };

let canShow = false; // True if the window is able to be shown.
let shouldShow = false; // True if the window should be shown when `canShow` value is changed to true.
let hasAutoShown = false; // True if the window has already been auto shown.

let getShouldAutoShowPromise: Promise<boolean>;
const getShouldAutoShow = async () => {
    if (!getShouldAutoShowPromise) {
        getShouldAutoShowPromise = (async () => {
            const opts = (await getCurrentOFWindow().getOptions()) as InternalWindowOptions;

            return !!opts?.workspacePlatform?._internalDeferShowOptions?.autoShow;
        })();
    }
    return getShouldAutoShowPromise;
};

const getDeferShowOptions = async () => {
    const opts = (await getCurrentOFWindow().getOptions()) as InternalWindowOptions;

    return {
        shouldSetAsForeground: !!opts?.workspacePlatform?._internalDeferShowOptions?.setAsForeground,
        shouldBeMinimized: !!opts.state && opts.state === 'minimized',
        shouldBeMaximized: !!opts.state && opts.state === 'maximized',
        alwaysOnTop: !!opts.alwaysOnTop
    };
};

/**
 * Assert if the window is able to be shown or not.
 * Upon calling `setCanShow(true)`, if the window was previously prevented
 * from being shown, this function will show the window.
 * @param bool true if the window should be able to be shown. (Default is false)
 */
export const setCanShow = async (bool: boolean) => {
    log.debug('defer-show: setCanShow called', {
        windowName: finName,
        bool,
        previousCanShow: canShow,
        shouldShow,
        hasAutoShown
    });
    canShow = bool;
    if (!canShow || !isFin || !fin.me.isWindow) {
        log.debug('defer-show: setCanShow early return', { canShow, isFin, isWindow: isFin && fin.me.isWindow });
        return;
    }

    // Check if the window was previously requested to be shown.
    const shouldAutoShow = await getShouldAutoShow();
    const { alwaysOnTop, shouldSetAsForeground, shouldBeMinimized, shouldBeMaximized } = await getDeferShowOptions();
    log.debug('defer-show: setCanShow options', {
        shouldAutoShow,
        shouldShow,
        hasAutoShown,
        shouldSetAsForeground,
        shouldBeMinimized,
        shouldBeMaximized
    });

    if (shouldShow || (!hasAutoShown && shouldAutoShow)) {
        log.debug(`Window Name: ${finName}. Is ready to be shown`);

        hasAutoShown = true;
        shouldShow = false;

        const ofWindow = getCurrentOFWindow();

        if (shouldBeMinimized || shouldBeMaximized) {
            log.debug(`${shouldBeMaximized ? 'Maximizing' : 'Minimizing'} window: ${finName}. Due to deferred show`);
            shouldBeMinimized && (await ofWindow.minimize());
            shouldBeMaximized && (await ofWindow.maximize());
            return;
        }

        log.debug(`showing ${shouldSetAsForeground ? '& setting as foregroound ' : ''}due to deferred show`);

        await ofWindow.show();
        if (shouldSetAsForeground) {
            // when window is alwaysOnTop bringToFront will work as expected, else use alwaysOnTop toggle
            if (alwaysOnTop) {
                await ofWindow.bringToFront();
            } else {
                await ofWindow.updateOptions({ alwaysOnTop: true });
                await ofWindow.updateOptions({ alwaysOnTop: false });
            }
            await ofWindow.focus();
        }
    }
};

let listener: (() => Promise<void>) | undefined;

/**
 * Add a listener that defers showing the current window.
 * To allow the window to be shown, `setCanShow(true)` must be called.
 * Upon calling `setCanShow(true)`, if the window was previously prevented
 * from being shown, it will show.
 */
export const registerDeferShow = async () => {
    if (listener || !isFin || !fin.me.isWindow) return;
    log.debug('defer-show: registerDeferShow called', { windowName: finName });
    const isWindow = await isWindowRunning(currentOFIdentity);
    if (!isWindow) return;
    const win = getCurrentOFWindow();
    const opts = (await win.getOptions()) as InternalWindowOptions;
    if (!(opts as InternalWindowOptions)?.workspacePlatform?._internalDeferShowOptions?.deferShowEnabled) {
        log.debug('defer-show: defer show not enabled, returning');
        return;
    }
    log.debug('defer-show: Setting up show-requested listener', {
        windowName: finName,
        canShow,
        shouldShow,
        hasAutoShown,
        deferShowEnabled: opts?.workspacePlatform?._internalDeferShowOptions?.deferShowEnabled
    });
    listener = async () => {
        log.debug(`Window Name: ${finName}. Show requested.`, {
            canShow,
            shouldShow,
            hasAutoShown,
            windowState: await win.getState()
        });
        if (!canShow) {
            log.debug('defer-show: canShow is false, setting shouldShow to true', { windowName: finName });
            shouldShow = true; // When `canShow` is set to true, we need to show the window.
            return;
        }
        log.debug('defer-show: canShow is true, showing window immediately', { windowName: finName });
        await win.show(true); // The window can be shown, so force it to do so.
    };
    await win.addListener('show-requested', listener);
    log.debug('defer-show: show-requested listener registered successfully', { windowName: finName });
};
