import type OpenFin from '@openfin/core';

import {
    AddDefaultPagePayload,
    AttachedPage,
    CreateBookmarkNodeRequest,
    Page,
    PageWithUpdatableRuntimeAttribs,
    ReorderPagesForWindowPayload,
    ReparentAttachedPage,
    UpdateBookmarkNodeRequest,
    UpdatePageForWindowPayload
} from '@common/api/pages/shapes';
import { BrowserChannelAction, getChannelClient as getDirectBrowserChannelClient } from '@common/api/protocol/browser';
import { getBrowserChannelClient, WorkspacePlatformChannelAction } from '@common/api/protocol/workspace-platform';

import {
    createBookmarkNodeInternal,
    deleteBookmarkNodeInternal,
    getBookmarkNodeInternal,
    searchBookmarkNodesInternal,
    updateBookmarkNodeInternal
} from '@client-platform/api/browser/bookmarks';

import { getCurrentSync, OpenPageTabContextMenuPayload } from '@client-platform/index';
import {
    BrowserWindowModule,
    InternalOpenGlobalContextMenuRequest,
    InternalOpenPageTabContextMenuRequest,
    NavigationRequest,
    OpenGlobalContextMenuPayload,
    OpenSaveButtonContextMenuPayload,
    OpenSaveButtonContextMenuRequest,
    OpenSaveMenuRequest,
    OpenViewTabContextMenuPayload,
    OpenViewTabContextMenuRequest,
    ReparentPageRequest,
    SearchSitesRequest,
    SendUpdateVersionModalResponsePayload,
    ToolbarOptions,
    WindowStateButtonOptions,
    WindowTitle
} from '@client-platform/shapes';
import { AddPagesOptions } from '@enterprise-api/shapes';

export const getBrowserModule = (identity: OpenFin.Identity): BrowserWindowModule => {
    return {
        identity,
        openfinWindow: fin.Window.wrapSync(identity),
        _bookmarks: {
            _createBookmarkNode: async (req: CreateBookmarkNodeRequest) => {
                return createBookmarkNodeInternal(req);
            },
            _getBookmarkNode: async (id?: string) => {
                return getBookmarkNodeInternal(id);
            },
            _searchBookmarkNodes: async (query: string) => {
                return searchBookmarkNodesInternal(query);
            },
            _updateBookmarkNode: async (req: UpdateBookmarkNodeRequest) => {
                return updateBookmarkNodeInternal(req);
            },
            _deleteBookmarkNode: async (id: string) => {
                return deleteBookmarkNodeInternal(id);
            }
        },
        getPages: async (): Promise<AttachedPage[]> => {
            const client = await getBrowserChannelClient(identity);
            return client.dispatch(WorkspacePlatformChannelAction.GetPagesForWindow, identity);
        },
        getPage: async (pageId: string): Promise<AttachedPage> => {
            const client = await getBrowserChannelClient(identity);
            return client.dispatch(WorkspacePlatformChannelAction.GetPageForWindow, { identity, pageId });
        },
        addPage: async (page: PageWithUpdatableRuntimeAttribs): Promise<void> => {
            const browser = getCurrentSync().Browser.wrapSync(identity);
            // eslint-disable-next-line no-underscore-dangle
            return browser._addPage(page);
        },
        _addPage: async (
            page: PageWithUpdatableRuntimeAttribs,
            opts?: { index?: number; multiInstanceViewBehavior?: OpenFin.MultiInstanceViewBehavior }
        ): Promise<void> => {
            const client = await getBrowserChannelClient(identity);
            const payload = {
                identity,
                page,
                insertionIndex: opts?.index,
                multiInstanceViewBehavior: opts?.multiInstanceViewBehavior
            };
            return client.dispatch(WorkspacePlatformChannelAction.AddPage, payload);
        },
        _addPages: async (
            pages: Array<{
                page: PageWithUpdatableRuntimeAttribs;
                opts?: { multiInstanceViewBehavior?: OpenFin.MultiInstanceViewBehavior };
            }>,
            opts?: AddPagesOptions
        ): Promise<void> => {
            const client = await getBrowserChannelClient(identity);

            // Process pages with multiInstanceViewBehavior
            const processedPages = pages.map(({ page, opts: pageOpts }) => ({
                ...page,
                multiInstanceViewBehavior: pageOpts?.multiInstanceViewBehavior || 'duplicate'
            }));

            const payload = {
                identity,
                pages: processedPages,
                ...opts
            };

            return client.dispatch(WorkspacePlatformChannelAction.AttachPagesToWindow, payload);
        },
        removePage: async (id: Page['pageId']): Promise<void> => {
            const client = await getBrowserChannelClient(identity);
            return client.dispatch(WorkspacePlatformChannelAction.DetachPagesFromWindow, { identity, pageIds: [id] });
        },
        reparentPage: async (req: ReparentPageRequest): Promise<void> => {
            const browser = getCurrentSync().Browser.wrapSync(identity);
            // eslint-disable-next-line no-underscore-dangle
            return browser._reparentPage(req);
        },
        _reparentPage: async (req: ReparentPageRequest & { index?: number }): Promise<void> => {
            const { pageId: targetPageId } = req;
            const client = await getBrowserChannelClient(identity);

            const allPages: AttachedPage[] = await client.dispatch(
                WorkspacePlatformChannelAction.GetAllAttachedPages,
                undefined
            );

            // Cast as a ReparentAttachedPage in order to add multiInstanceViewBehavior
            const targetPage: ReparentAttachedPage = allPages.find(({ pageId }) => pageId === targetPageId);
            if (!targetPage) {
                throw new Error(`Reparent Page Error: Target page with pageId ${targetPageId} not found`);
            }
            targetPage.multiInstanceViewBehavior = 'reparent';
            const payload = {
                identity,
                pages: [targetPage],
                insertionIndex: req.index
            };
            return client.dispatch(WorkspacePlatformChannelAction.AttachPagesToWindow, payload);
        },
        setActivePage: async (id: Page['pageId']): Promise<void> => {
            const client = await getBrowserChannelClient(identity);
            return client.dispatch(WorkspacePlatformChannelAction.SetActivePage, { identity, pageId: id });
        },
        updatePage: async (req) => {
            const client = await getBrowserChannelClient(identity);
            (req as UpdatePageForWindowPayload).identity = identity;
            return client.dispatch(WorkspacePlatformChannelAction.UpdatePageForWindow, req);
        },
        reorderPages: async (req) => {
            const client = await getBrowserChannelClient(identity);
            (req as ReorderPagesForWindowPayload).identity = identity;
            return client.dispatch(WorkspacePlatformChannelAction.ReorderPagesForWindow, req);
        },
        _openGlobalContextMenu: async (req: InternalOpenGlobalContextMenuRequest) => {
            const client = await getBrowserChannelClient(identity);
            (req as OpenGlobalContextMenuPayload).identity = identity;
            return client.dispatch(WorkspacePlatformChannelAction.OpenGlobalContextMenuInternal, req);
        },
        replaceToolbarOptions: async (options: ToolbarOptions) => {
            await getBrowserChannelClient(identity);

            const openFinWindow = fin.Window.wrapSync(identity);
            // openFinWindow.updateOptions is expecting an updated object with full properties and not partial
            await openFinWindow.updateOptions({
                workspacePlatform: { toolbarOptions: options } as any
            });
        },
        replaceWindowStateButtonOptions: async (options: WindowStateButtonOptions) => {
            await getBrowserChannelClient(identity);

            const openFinWindow = fin.Window.wrapSync(identity);
            await openFinWindow.updateOptions({
                workspacePlatform: { windowStateButtonOptions: options } as any
            });
        },
        updateBrowserWindowTitle: async (title: WindowTitle) => {
            const openFinWindow = fin.Window.wrapSync(identity);
            if (typeof title === 'string') {
                console.warn('Type string for window title is deprecated, please use WindowTitle type instead', title);
                return;
            }
            await openFinWindow.updateOptions({
                workspacePlatform: { title }
            });
        },
        _openViewTabContextMenu: async (req: OpenViewTabContextMenuRequest) => {
            const client = await getBrowserChannelClient(identity);
            (req as OpenViewTabContextMenuPayload).identity = identity;
            return client.dispatch(WorkspacePlatformChannelAction.OpenViewTabContextMenuInternal, req);
        },
        _openPageTabContextMenu: async (req: InternalOpenPageTabContextMenuRequest) => {
            const client = await getBrowserChannelClient(identity);
            (req as OpenPageTabContextMenuPayload).identity = identity;
            return client.dispatch(WorkspacePlatformChannelAction.OpenPageTabContextMenuInternal, req);
        },
        _openSaveModal: async (req: OpenSaveMenuRequest) => {
            await getBrowserChannelClient(identity);

            const client = await getDirectBrowserChannelClient(identity);
            return client.dispatch(BrowserChannelAction.OpenSaveModalInternal, req);
        },
        _getLayoutsWithSelectedViews: async () => {
            const client = await getDirectBrowserChannelClient(identity);
            return client.dispatch(BrowserChannelAction.GetLayoutsWithSelectedViewsInternal, identity);
        },
        _openSaveButtonContextMenu: async (req: OpenSaveButtonContextMenuRequest) => {
            const client = await getBrowserChannelClient(identity);
            (req as OpenSaveButtonContextMenuPayload).identity = identity;
            return client.dispatch(WorkspacePlatformChannelAction.OpenSaveButtonContextMenuInternal, req);
        },
        _addDefaultPage: async (req: Omit<AddDefaultPagePayload, 'identity'>): Promise<void> => {
            const client = await getBrowserChannelClient(identity);
            (req as AddDefaultPagePayload).identity = identity;
            return client.dispatch(WorkspacePlatformChannelAction.AddDefaultPage, req);
        },
        _trackRemovedTab: async (req: any) => {
            const client = await getBrowserChannelClient(identity);
            return client.dispatch(WorkspacePlatformChannelAction.TrackRemovedTabInternal, req);
        },
        _restoreRemovedTab: async (req: any) => {
            const client = await getBrowserChannelClient(identity);
            return client.dispatch(WorkspacePlatformChannelAction.RestoreRemovedTabInternal, req);
        },
        _trackVisitedSite: async (req: any) => {
            const client = await getBrowserChannelClient(identity);
            return client.dispatch(WorkspacePlatformChannelAction.TrackVisitedSiteInternal, req);
        },
        _getRecentlyVisitedSites: async (req: any) => {
            const client = await getBrowserChannelClient(identity);
            return client.dispatch(WorkspacePlatformChannelAction.GetRecentlyVisitedSitesInternal, req);
        },
        _getFrequentlyVisitedSites: async (req: any) => {
            const client = await getBrowserChannelClient(identity);
            return client.dispatch(WorkspacePlatformChannelAction.GetFrequentlyVisitedSitesInternal, req);
        },
        _searchSites: async (req: SearchSitesRequest) => {
            const client = await getBrowserChannelClient(identity);
            return client.dispatch(WorkspacePlatformChannelAction.SearchSitesInternal, { identity, req });
        },
        _getSearchProviders: async () => {
            const client = await getBrowserChannelClient(identity);
            return client.dispatch(WorkspacePlatformChannelAction.GetSearchProvidersInternal, { identity });
        },
        _getCuratedContent: async (req?: any) => {
            const client = await getBrowserChannelClient(identity);
            return client.dispatch(WorkspacePlatformChannelAction.GetCuratedContentInternal, { identity, req });
        },
        _handleRequestNavigation: async (args: NavigationRequest) => {
            const client = await getBrowserChannelClient(identity);
            return client.dispatch(WorkspacePlatformChannelAction.HandleRequestNavigationInternal, args);
        },
        _sendUpdateVersionModalResponse: async (payload: SendUpdateVersionModalResponsePayload) => {
            const client = await getBrowserChannelClient(identity);
            return client.dispatch(WorkspacePlatformChannelAction.SendUpdateVersionModalResponseInternal, payload);
        }
    };
};
