import { MenuItemType } from '@common/utils/context-menu';

import { t } from '@common/api/i18next';

import * as WP from '@client-platform/index';
import { SaveButtonContextMenuItemTemplate, SaveButtonContextMenuOptionType } from '@client-platform/shapes';

export const getSaveButtonMenuTemplate = async (pageId: string): Promise<SaveButtonContextMenuItemTemplate[]> => {
    const platform = WP.getCurrentSync();
    const activeWorkspace = await platform.getCurrentWorkspace({ skipSnapshotUpdate: true });
    const savedWorkspaces = await platform.Storage.getWorkspacesMetadata();
    const lastSavedWorkspace = savedWorkspaces.find(
        (workspace) => workspace.workspaceId === activeWorkspace.workspaceId
    );

    const savedPage = await platform.Storage.getPage(pageId);

    return [
        {
            type: MenuItemType.Label,
            label: t('contextMenu.saveWorkspace'),
            enabled: !!lastSavedWorkspace,
            data: {
                type: SaveButtonContextMenuOptionType.SaveWorkspace
            }
        },
        {
            type: MenuItemType.Label,
            label: t('saveMenu.saveWorkspaceAs'),
            data: {
                type: SaveButtonContextMenuOptionType.SaveWorkspaceAs
            }
        },
        { type: MenuItemType.Separator, data: undefined },
        {
            type: MenuItemType.Label,
            enabled: !!savedPage,
            label: t('contextMenu.savePage'),
            data: {
                type: SaveButtonContextMenuOptionType.SavePage
            }
        },
        {
            type: MenuItemType.Label,
            label: t('saveMenu.savePageAs'),
            data: {
                type: SaveButtonContextMenuOptionType.SavePageAs
            }
        }
    ];
};
