import makeGetChannelClient from '@common/utils/channels';

import { BookmarkNode, CreateBookmarkNodeRequest, UpdateBookmarkNodeRequest } from '@common/api/pages/shapes';
import { EnterpriseBookmarkChannelAction } from '@common/api/protocol/browser';

const enterpriseBookmarksChannelClient = makeGetChannelClient(
    `${typeof fin !== 'undefined' && fin?.me.identity.uuid}-enterprise-bookmarks`
);

export const createBookmarkNodeInternal = async (req: CreateBookmarkNodeRequest): Promise<BookmarkNode> => {
    const channel = await enterpriseBookmarksChannelClient();
    return channel.dispatch(EnterpriseBookmarkChannelAction.CreateBookmarkNode, req);
};

export const getBookmarkNodeInternal = async (id?: string): Promise<BookmarkNode | undefined> => {
    const channel = await enterpriseBookmarksChannelClient();
    return channel.dispatch(EnterpriseBookmarkChannelAction.GetBookmarkNode, id);
};

export const searchBookmarkNodesInternal = async (query: string): Promise<BookmarkNode[]> => {
    const channel = await enterpriseBookmarksChannelClient();
    return channel.dispatch(EnterpriseBookmarkChannelAction.SearchBookmarkNodes, query);
};

export const updateBookmarkNodeInternal = async (req: UpdateBookmarkNodeRequest): Promise<BookmarkNode | undefined> => {
    const channel = await enterpriseBookmarksChannelClient();
    return channel.dispatch(EnterpriseBookmarkChannelAction.UpdateBookmarkNode, req);
};

export const deleteBookmarkNodeInternal = async (id: string): Promise<void> => {
    const channel = await enterpriseBookmarksChannelClient();
    return channel.dispatch(EnterpriseBookmarkChannelAction.DeleteBookmarkNode, id);
};
