import { createAsyncThunk, createSlice, PayloadAction } from '@reduxjs/toolkit';

import type OpenFin from '@openfin/core';

import {
    debouncedSetContextHighlighting,
    highlightAllInteropViews,
    removeInteropOutlines
} from '@enterprise/api/color-linking';

import { AttachedPagesRootState, selectPage } from './pages/attached';

const EMPTY_VIEWS: OpenFin.Identity[] = [];

export interface TabFocusRootState {
    tabFocus: {
        showAllContextGroups: boolean;
        layoutsWithSelectedViews: Record<string, OpenFin.Identity[]>;
        /** The specific view that was last focused via a view-focused event (prevents re-focusing) */
        lastViewFocusedViaEvent: OpenFin.Identity | null;
    };
}

// Combined state type for selectors that need both tabFocus and attachedPages
type TabFocusWithPagesState = TabFocusRootState & AttachedPagesRootState;

export const tabFocusSlice = createSlice({
    name: 'tab-focus',
    initialState: {
        showAllContextGroups: false,
        layoutsWithSelectedViews: {},
        lastViewFocusedViaEvent: null
    } as TabFocusRootState['tabFocus'],
    reducers: {
        /**
         * Select a single view
         */
        selectViewReducer: (
            state,
            action: PayloadAction<{ viewId: OpenFin.Identity; layoutContainerKey: string; fromFocusEvent?: boolean }>
        ) => {
            const { viewId, layoutContainerKey, fromFocusEvent } = action.payload;
            state.layoutsWithSelectedViews[layoutContainerKey] = [viewId];
            // Track which view was focused via OpenFin event to prevent re-focus loops
            state.lastViewFocusedViaEvent = fromFocusEvent ? viewId : null;
            debouncedSetContextHighlighting([viewId], layoutContainerKey);
        },
        /**
         * Add a view to the list of currently selected views (multi-select);
         */
        addSelectedViewReducer: (
            state,
            action: PayloadAction<{ viewId: OpenFin.Identity; layoutContainerKey: string }>
        ) => {
            const { layoutContainerKey, viewId } = action.payload;
            state.layoutsWithSelectedViews[layoutContainerKey] = [
                ...state.layoutsWithSelectedViews[layoutContainerKey],
                viewId
            ];
            debouncedSetContextHighlighting(state.layoutsWithSelectedViews[layoutContainerKey], layoutContainerKey);
        },
        /**
         * Clears selected view from a specified page
         */
        clearSelectedViewsReducer: (state, action: PayloadAction<{ layoutContainerKey: string }>) => {
            const { layoutContainerKey } = action.payload;
            state.layoutsWithSelectedViews[layoutContainerKey] = [];
        },
        /**
         * Delete entry for pageId from pagesWithSelectedViews
         */
        deletePageWithSelectedViewsReducer: (state, action: PayloadAction<string>) => {
            delete state.layoutsWithSelectedViews[action.payload];
        },
        toggleContextGroupOutlines: (state) => {
            const newState = !state.showAllContextGroups;
            state.showAllContextGroups = newState;

            if (newState) {
                highlightAllInteropViews();
            } else {
                removeInteropOutlines();
            }
        }
    }
});

export const selectView = createAsyncThunk(
    'tab-focus/selectView',
    async (
        { viewId, pageId, fromFocusEvent }: { viewId: OpenFin.Identity; pageId: string; fromFocusEvent?: boolean },
        { getState, dispatch }
    ) => {
        const layoutContainerKey = selectPage(getState() as AttachedPagesRootState, pageId).layoutContainerKey;
        dispatch(tabFocusSlice.actions.selectViewReducer({ viewId, layoutContainerKey, fromFocusEvent }));
    }
);

export const selectViewForLayoutContainerKey = createAsyncThunk(
    'tab-focus/selectView',
    async ({ viewId, layoutContainerKey }: { viewId: OpenFin.Identity; layoutContainerKey: string }, { dispatch }) => {
        dispatch(tabFocusSlice.actions.selectViewReducer({ viewId, layoutContainerKey }));
    }
);

export const addSelectedView = createAsyncThunk(
    'tab-focus/addSelectedView',
    async ({ viewId, pageId }: { viewId: OpenFin.Identity; pageId: string }, { getState, dispatch }) => {
        const layoutContainerKey = selectPage(getState() as AttachedPagesRootState, pageId).layoutContainerKey;
        dispatch(tabFocusSlice.actions.addSelectedViewReducer({ viewId, layoutContainerKey }));
    }
);

export const clearSelectedViews = createAsyncThunk(
    'tab-focus/clearSelectedViews',
    async ({ pageId }: { pageId: string }, { getState, dispatch }) => {
        const layoutContainerKey = selectPage(getState() as AttachedPagesRootState, pageId).layoutContainerKey;
        dispatch(tabFocusSlice.actions.clearSelectedViewsReducer({ layoutContainerKey }));
    }
);

export const deletePageWithSelectedViews = createAsyncThunk(
    'tab-focus/deletePageWithSelectedViews',
    async (pageId: string, { getState, dispatch }) => {
        const layoutContainerKey = selectPage(getState() as AttachedPagesRootState, pageId).layoutContainerKey;
        dispatch(tabFocusSlice.actions.deletePageWithSelectedViewsReducer(layoutContainerKey));
    }
);

export const { toggleContextGroupOutlines, selectViewReducer } = tabFocusSlice.actions;

export const selectShowAllContextGroups = (state: TabFocusRootState) => state.tabFocus.showAllContextGroups;

// The following 3 selectors return an array of objects. react will do shallow comparison and consider the value has changed
// even if the name or uuid are the same after a focus change. This will trigger a re-render in the component.
// Consider using reselect with memoized deep equal selectors in the future.
export const selectSelectedViewsForPage = (state: TabFocusWithPagesState, pageId: string) => {
    const layoutContainerKey = selectPage(state, pageId).layoutContainerKey;
    return state.tabFocus.layoutsWithSelectedViews[layoutContainerKey] || EMPTY_VIEWS;
};

export const selectSelectedViewsForLayoutContainerKey =
    (layoutContainerKey: string) => (state: TabFocusWithPagesState) => {
        return state.tabFocus.layoutsWithSelectedViews[layoutContainerKey] || EMPTY_VIEWS;
    };

export const selectLayoutsWithSelectedViews = (state: TabFocusRootState) => state.tabFocus.layoutsWithSelectedViews;

export const selectFirstViewNameForLayoutContainerKey =
    (layoutContainerKey: string) => (state: TabFocusWithPagesState) => {
        return selectSelectedViewsForLayoutContainerKey(layoutContainerKey)(state)?.[0]?.name;
    };

export const selectFirstViewIdForLayoutContainerKey =
    (layoutContainerKey: string) => (state: TabFocusWithPagesState) => {
        return selectSelectedViewsForLayoutContainerKey(layoutContainerKey)(state)?.[0]?.uuid;
    };

export const selectLastViewFocusedViaEvent = (state: TabFocusRootState) => state.tabFocus.lastViewFocusedViaEvent;

export default tabFocusSlice.reducer;
