import OpenFin from '@openfin/core';

import { workspaceBuildVersion } from '@common/utils/env';

import { getCurrentSync } from '@client-platform/api';

const CONTEXT_MENU_CHANNEL = 'custom-context-menu';

const CONTEXT_BOOKMARK_MENU_CHANNEL = 'custom-bookmark-context-menu';

const DROPDOWN_MENU_CHANNEL = 'custom-dropdown-menu';

const BOOKMARK_PANEL_ACTIONS_MONITOR = 'custom-bookmark-panel-actions-monitor';

const TAB_SEARCH_CHANNEL = 'tab-search-menu';

const ZOOM_CONTROLS_DIALOG_CHANNEL = 'zoom-controls-dialog';

let contextMenuChannel: OpenFin.ChannelClient | undefined;

export const getContextMenuChannelName = () => {
    const platform = getCurrentSync();
    return `${CONTEXT_MENU_CHANNEL}-${platform.identity.uuid}-${workspaceBuildVersion}`;
};

export const getBookmarkContextMenuChannelName = () => {
    const platform = getCurrentSync();
    return `${CONTEXT_BOOKMARK_MENU_CHANNEL}-${platform.identity.uuid}-${workspaceBuildVersion}`;
};

export const getBookmarkPanelActionsMonitorChannelName = () => {
    const platform = getCurrentSync();
    return `${BOOKMARK_PANEL_ACTIONS_MONITOR}-${platform.identity.uuid}-${workspaceBuildVersion}`;
};

export const getDropdownMenuChannelName = () => {
    const platform = getCurrentSync();
    return `${DROPDOWN_MENU_CHANNEL}-${platform.identity.uuid}-${workspaceBuildVersion}`;
};

export const getZoomControlsDialogChannelName = () => {
    const platform = getCurrentSync();
    return `${ZOOM_CONTROLS_DIALOG_CHANNEL}-${platform.identity.uuid}-${workspaceBuildVersion}`;
};

export const createDropdownMenuChannel = (): Promise<OpenFin.ChannelProvider> =>
    fin.InterApplicationBus.Channel.create(getDropdownMenuChannelName());
export const connectDropdownMenuChannel = (): Promise<OpenFin.ChannelClient> =>
    fin.InterApplicationBus.Channel.connect(getDropdownMenuChannelName());

export const createBookmarkDialogChannel = (): Promise<OpenFin.ChannelProvider> =>
    fin.InterApplicationBus.Channel.create(getBookmarkContextMenuChannelName());
export const connectToBookmarkDialogChannel = (): Promise<OpenFin.ChannelClient> =>
    fin.InterApplicationBus.Channel.connect(getBookmarkContextMenuChannelName());

export const createBookmarkPanelActionsMonitorChannel = (): Promise<OpenFin.ChannelProvider> =>
    fin.InterApplicationBus.Channel.create(getBookmarkPanelActionsMonitorChannelName());
export const connectToBookmarkPanelActionsMonitor = (): Promise<OpenFin.ChannelClient> =>
    fin.InterApplicationBus.Channel.connect(getBookmarkPanelActionsMonitorChannelName());

export const createContextMenuChannel = (): Promise<OpenFin.ChannelProvider> =>
    fin.InterApplicationBus.Channel.create(getContextMenuChannelName());
export const connectToContextMenuChannel = async (): Promise<OpenFin.ChannelClient> => {
    if (!contextMenuChannel) {
        contextMenuChannel = await fin.InterApplicationBus.Channel.connect(getContextMenuChannelName());
    }
    return contextMenuChannel;
};

export const connectToEnterpriseContentChannel = (uuid: string): Promise<OpenFin.ChannelClient> =>
    fin.InterApplicationBus.Channel.connect(`${uuid}-enterprise-app-directory`);

export const connectToEnterpriseModalChannel = (uuid: string): Promise<OpenFin.ChannelClient> =>
    fin.InterApplicationBus.Channel.connect(`${uuid}-enterprise-modal`);

export const createZoomControlsDialogChannel = (): Promise<OpenFin.ChannelProvider> =>
    fin.InterApplicationBus.Channel.create(getZoomControlsDialogChannelName());
export const connectToZoomControlsDialogChannel = (): Promise<OpenFin.ChannelClient> =>
    fin.InterApplicationBus.Channel.connect(getZoomControlsDialogChannelName());

export const getTabSearchChannelName = () => {
    const platform = getCurrentSync();
    return `${TAB_SEARCH_CHANNEL}-${platform.identity.uuid}-${workspaceBuildVersion}`;
};

export const createTabSearchChannel = (): Promise<OpenFin.ChannelProvider> =>
    fin.InterApplicationBus.Channel.create(getTabSearchChannelName());
export const connectToTabSearchChannel = (): Promise<OpenFin.ChannelClient> =>
    fin.InterApplicationBus.Channel.connect(getTabSearchChannelName());
