import { AiPanelOptions, BrowserInitConfig } from '@client-platform/shapes';

let isEnterprisePlatform = false;
let aiPanelOptions: AiPanelOptions | undefined;

export const setIsEnterprisePlatform = (value: boolean) => {
    isEnterprisePlatform = value;
};

export const getIsEnterprisePlatform = (): boolean => {
    return isEnterprisePlatform;
};

export const getAiPanelOptions = (): AiPanelOptions => {
    return aiPanelOptions || { enabled: false };
};

export const setAiPanelOptions = (browserInitOptions: BrowserInitConfig): AiPanelOptions => {
    aiPanelOptions = browserInitOptions?.aiPanelOptions;
    return getAiPanelOptions();
};
