import type OpenFin from '@openfin/core';

import { createLogger } from '@common/utils/logger';
import Route from '@common/utils/route';

import { BrowserInitConfig } from '@client-platform/shapes';

import { currentOFIdentity, WindowName } from './window';

const logger = createLogger('common.enterpriseBrowser');

export const DEFAULT_ENTERPRISE_WINDOW_HEIGHT = 600;
export const DEFAULT_ENTERPRISE_WINDOW_WIDTH = 900;

export const ENTERPRISE_MIN_WINDOW_HEIGHT = 488;
export const ENTERPRISE_MIN_WINDOW_WIDTH = 654;

export const isEnterpriseBrowser = async (id?: OpenFin.Identity): Promise<boolean> => {
    const window = id ? fin.Window.wrapSync(id) : fin.Window.getCurrentSync();
    const opts = await window.getOptions();
    return opts.workspacePlatform?.windowType && opts.workspacePlatform.windowType === 'enterprise';
};

export const isEnterpriseBrowserPlatform = (browserInitOptions: BrowserInitConfig) => {
    const windowType = browserInitOptions?.defaultWindowOptions?.workspacePlatform?.windowType;
    return windowType === 'enterprise';
};

export function formatUrl(url: string): string {
    if (!url) {
        return '';
    }
    return url.replace(/^(https?:\/\/)?(www\.)?/, '').replace(/\/$/, '');
}

// for improved efficiency, use when isEnterpriseBrowser multiple times in same file
let isEnterpriseResult: boolean;
export const getIsEnterpriseBrowser = async (id?: OpenFin.Identity): Promise<boolean> => {
    if (!isEnterpriseResult) {
        isEnterpriseResult = await isEnterpriseBrowser(id);
    }
    return isEnterpriseResult;
};

export const isLandingPage = (url: string) => {
    if (url) {
        try {
            const urlObj = new URL(url);
            return urlObj.pathname.includes(Route.EnterpriseLandingPage.replace(/\/$/, ''));
        } catch (err) {
            logger.error('isLandingPage', 'Error parsing url', { url });
        }
    }
    return false;
};

export const isLandingPageOrEmpty = (url: string) => {
    return isLandingPage(url) || url === '';
};

export const isDefaultEnterpriseView = (viewIdentity: OpenFin.Identity) => {
    return (
        viewIdentity.name.startsWith(WindowName.BrowserAddressSearchPrefix) ||
        viewIdentity.name.startsWith(WindowName.AICompanionPrefix)
    );
};

export const getAICompanionViewIdentity = (browserIdentity?: OpenFin.Identity) => {
    return {
        uuid: (browserIdentity ?? currentOFIdentity).uuid,
        name: WindowName.AICompanionPrefix + (browserIdentity ?? currentOFIdentity).name
    };
};

export const getSearchMenuViewIdentity = (browserIdentity?: OpenFin.Identity) => {
    return {
        uuid: (browserIdentity ?? currentOFIdentity).uuid,
        name: WindowName.BrowserAddressSearchPrefix + (browserIdentity ?? currentOFIdentity).name
    };
};
